tool_schemas.implementation:
def extract_resume(workspace_id, resume_id=None, title=None, source_type=None, raw_text=None, raw_file_url=None, raw_file_mime=None, raw_file_sha256=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers ----
    def _log(endpoint, status, workspace_id=None, job_id=None, idempotency_key=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rmz_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "job_id": job_id,
            "idempotency_key": idempotency_key,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex.upper()

    def _month_prefix(ts_iso):
        # expects Z; fallback to current
        try:
            dt = datetime.datetime.fromisoformat(ts_iso.replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime.utcnow()
        return f"{dt.year:04d}-{dt.month:02d}"

    def _validate_pattern(val, pat, field):
        if val is None:
            return None
        if not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string")
        if not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"{field} is malformed")
        return None

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad workspace_id")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    e = _validate_pattern(resume_id, r"^rmz_rsm_[0-9A-Z]{18,}$", "resume_id")
    if e:
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad resume_id")
        return e
    if title is not None and not isinstance(title, str):
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad title type")
        return _err("VALIDATION_ERROR", "title must be a string")
    if source_type is not None:
        if not isinstance(source_type, str) or source_type not in ("upload", "paste", "generated"):
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad source_type")
            return _err("VALIDATION_ERROR", "source_type must be one of: upload, paste, generated")
    if raw_text is not None and not isinstance(raw_text, str):
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad raw_text type")
        return _err("VALIDATION_ERROR", "raw_text must be a string")
    if raw_file_url is not None and not isinstance(raw_file_url, str):
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad raw_file_url type")
        return _err("VALIDATION_ERROR", "raw_file_url must be a string")
    if raw_file_mime is not None and not isinstance(raw_file_mime, str):
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad raw_file_mime type")
        return _err("VALIDATION_ERROR", "raw_file_mime must be a string")
    if raw_file_sha256 is not None:
        if not isinstance(raw_file_sha256, str) or not re.match(r"^[A-Fa-f0-9]{64}$", raw_file_sha256):
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad raw_file_sha256")
            return _err("VALIDATION_ERROR", "raw_file_sha256 is malformed")

    if source_type == "paste":
        if not raw_text or not isinstance(raw_text, str) or not raw_text.strip():
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="paste missing raw_text")
            return _err("VALIDATION_ERROR", "raw_text is required when source_type='paste'")
    if source_type == "upload":
        if not raw_file_url or not isinstance(raw_file_url, str) or not raw_file_url.strip():
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="upload missing raw_file_url")
            return _err("VALIDATION_ERROR", "raw_file_url is required when source_type='upload'")
        if raw_file_sha256 is None:
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="upload missing sha256")
            return _err("VALIDATION_ERROR", "raw_file_sha256 is required when source_type='upload'")

    # ---- ambient auth: workspace must exist and be usable ----
    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp:
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="workspace not found")
        return _err("NOT_FOUND", "workspace not found")
    if wsp.get("status") in ("suspended", "deleted"):
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="workspace not active")
        return _err("UNAUTHORIZED", "workspace is not active")

    # ---- idempotency: unique(workspace_id, tool_name, idempotency_key) ----
    jobs = _load("processing_jobs.json")
    if idempotency_key is not None:
        if not isinstance(idempotency_key, str) or not idempotency_key.strip():
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad idempotency_key")
            return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
        for j in jobs:
            if isinstance(j, dict) and j.get("workspace_id") == workspace_id and j.get("tool_name") == "extract_resume" and j.get("idempotency_key") == idempotency_key:
                # return original
                rid = j.get("resume_id")
                resumes = _load("resumes.json")
                r = next((x for x in resumes if isinstance(x, dict) and x.get("id") == rid), None)
                _log("extract_resume", "ok", workspace_id=workspace_id, job_id=j.get("id"), idempotency_key=idempotency_key, detail="idempotent replay")
                return {"resume": r, "job": j}

    # ---- quota enforcement at queued creation time ----
    month = _month_prefix(now)
    month_jobs = 0
    month_tokens = 0
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("workspace_id") != workspace_id:
            continue
        created_at = j.get("created_at") or ""
        if isinstance(created_at, str) and created_at.startswith(month):
            month_jobs += 1
            month_tokens += int(j.get("prompt_tokens") or 0) + int(j.get("completion_tokens") or 0)
    limit_jobs = int(wsp.get("monthly_job_limit") or 0)
    limit_tokens = int(wsp.get("monthly_token_limit") or 0)
    # projected token usage for extract is ~0
    if month_jobs + 1 > limit_jobs:
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="monthly job limit exceeded")
        return _err("QUOTA_EXCEEDED", "monthly job limit exceeded", limit=limit_jobs)
    if month_tokens > limit_tokens:
        _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="monthly token limit exceeded")
        return _err("QUOTA_EXCEEDED", "monthly token limit exceeded", limit=limit_tokens)

    resumes = _load("resumes.json")

    # ---- find/create resume ----
    r = None
    if resume_id:
        r = next((x for x in resumes if isinstance(x, dict) and x.get("id") == resume_id and x.get("workspace_id") == workspace_id), None)
        if not r:
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="resume not found")
            return _err("NOT_FOUND", "resume not found")
        if r.get("status") == "deleted":
            _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="resume deleted")
            return _err("INVALID_TRANSITION", "cannot update a deleted resume")
    else:
        resume_id = _gen_id("rmz_rsm_")
        r = {
            "id": resume_id,
            "workspace_id": workspace_id,
            "status": "draft",
            "source_type": source_type or "upload",
            "title": title if title is not None else None,
            "raw_text": None,
            "raw_file_url": None,
            "raw_file_mime": None,
            "raw_file_sha256": None,
            "parsed_resume_json": None,
            "parsed_schema_version": "v1",
            "anonymized_resume_json": None,
            "latest_generated_resume_text": None,
            "latest_generated_format": None,
            "latest_cover_letter_text": None,
            "created_at": now,
            "updated_at": now
        }
        resumes.append(r)

    # ---- uniqueness constraint: unique(workspace_id, raw_file_sha256) where not null ----
    if raw_file_sha256 is not None:
        for other in resumes:
            if not isinstance(other, dict):
                continue
            if other.get("workspace_id") == workspace_id and other.get("raw_file_sha256") == raw_file_sha256 and other.get("id") != r.get("id") and other.get("status") != "deleted":
                _log("extract_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="duplicate sha256")
                return _err("CONFLICT", "a resume with the same raw_file_sha256 already exists in this workspace", resume_id=other.get("id"))

    # ---- attach/replace raw content ----
    if source_type is not None:
        r["source_type"] = source_type
    if title is not None:
        r["title"] = title

    if r.get("source_type") == "paste":
        r["raw_text"] = raw_text
        r["raw_file_url"] = None
        r["raw_file_mime"] = None
        r["raw_file_sha256"] = None
    elif r.get("source_type") == "upload":
        r["raw_file_url"] = raw_file_url
        r["raw_file_mime"] = raw_file_mime
        r["raw_file_sha256"] = raw_file_sha256
        # extraction will populate raw_text
    elif r.get("source_type") == "generated":
        # allow caller to provide raw_text; if not present, keep existing
        if raw_text is not None:
            r["raw_text"] = raw_text

    r["updated_at"] = now

    # ---- create processing job: queued -> running -> succeeded/failed ----
    job_id = _gen_id("rmz_job_")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": r.get("id"),
        "linkedin_profile_id": None,
        "tool_name": "extract_resume",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {
            "workspace_id": workspace_id,
            "resume_id": r.get("id"),
            "title": title,
            "source_type": r.get("source_type"),
            "raw_text": raw_text if r.get("source_type") == "paste" else None,
            "raw_file_url": raw_file_url if r.get("source_type") == "upload" else None,
            "raw_file_mime": raw_file_mime if r.get("source_type") == "upload" else None,
            "raw_file_sha256": raw_file_sha256 if r.get("source_type") == "upload" else None
        },
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": 0,
        "completion_tokens": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    # persist creation before running (observable dynamics)
    _save("resumes.json", resumes)
    _save("processing_jobs.json", jobs)

    # transition: queued -> running
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # perform extraction "successfully" based on stored inputs (offline)
    extracted_text = None
    try:
        if r.get("source_type") == "paste":
            extracted_text = (r.get("raw_text") or "").strip()
        elif r.get("source_type") == "upload":
            # no file IO; derive placeholder extraction from URL + hash
            extracted_text = f"EXTRACTED_TEXT_FROM_FILE({r.get('raw_file_url')})"
        elif r.get("source_type") == "generated":
            extracted_text = (r.get("raw_text") or "").strip() if r.get("raw_text") else "GENERATED_RESUME_CONTENT"
        else:
            extracted_text = (r.get("raw_text") or "").strip()
    except Exception:
        extracted_text = None

    if extracted_text is None or not isinstance(extracted_text, str) or not extracted_text.strip():
        job["status"] = "failed"
        job["error_code"] = "EXTRACTION_FAILED"
        job["error_message"] = "Unable to extract resume text from provided content."
        job["finished_at"] = now
        job["updated_at"] = now
        # resume stays draft/processing? We'll set back to draft if it was processing
        if r.get("status") == "processing":
            r["status"] = "draft"
            r["updated_at"] = now
        _save("resumes.json", resumes)
        _save("processing_jobs.json", jobs)
        _log("extract_resume", "error", workspace_id=workspace_id, job_id=job_id, idempotency_key=idempotency_key, detail="extraction failed")
        return _err("CONFLICT", "extraction failed", job=job)

    # update resume: populate raw_text and set status ready
    # transitions allowed: draft->ready, processing->ready, ready->ready not declared but we treat as no-op? must be legal.
    prev = r.get("status")
    if prev == "deleted":
        job["status"] = "failed"
        job["error_code"] = "RESUME_DELETED"
        job["error_message"] = "Resume was deleted."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)
        _log("extract_resume", "error", workspace_id=workspace_id, job_id=job_id, idempotency_key=idempotency_key, detail="resume deleted mid-flight")
        return _err("INVALID_TRANSITION", "cannot extract into a deleted resume", job=job)

    # set to processing first if needed
    allowed_to_processing = prev in ("draft", "ready")
    if allowed_to_processing:
        r["status"] = "processing"
        r["updated_at"] = now
        _save("resumes.json", resumes)

    r["raw_text"] = extracted_text
    # final: processing/draft->ready or archived->? archived->ready allowed; keep archived? rule says set to ready on success
    if r.get("status") in ("draft", "processing", "archived", "ready"):
        r["status"] = "ready"
    else:
        # unknown, don't proceed
        job["status"] = "failed"
        job["error_code"] = "INVALID_STATUS"
        job["error_message"] = f"Resume status {r.get('status')} cannot transition to ready."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)
        _log("extract_resume", "error", workspace_id=workspace_id, job_id=job_id, idempotency_key=idempotency_key, detail="invalid resume status transition")
        return _err("INVALID_TRANSITION", "resume cannot transition to ready from current status", current_status=r.get("status"), job=job)

    r["updated_at"] = now

    job["status"] = "succeeded"
    job["output_json"] = {"resume_id": r.get("id"), "extracted_text_length": len(extracted_text)}
    job["finished_at"] = now
    job["updated_at"] = now

    _save("resumes.json", resumes)
    _save("processing_jobs.json", jobs)

    _log("extract_resume", "ok", workspace_id=workspace_id, job_id=job_id, idempotency_key=idempotency_key)
    return {"resume": r, "job": job}

def parse_resume(workspace_id, resume_id, schema_version=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status, error_code=None, workspace_id_used=None, job_id=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "rmz_req_" + uuid.uuid4().hex.upper()[:19],
            "timestamp": now,
            "endpoint": "parse_resume",
            "workspace_id": workspace_id_used,
            "job_id": job_id,
            "status": status,
            "latency_ms": latency_ms,
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _job_month(job):
        ts = job.get("created_at") or job.get("timestamp") or job.get("started_at") or job.get("updated_at")
        if not isinstance(ts, str) or not ts:
            return _month_key(now_dt)
        try:
            d = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return _month_key(now_dt)
        return d.strftime("%Y-%m")

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:19]

    # ---- validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(resume_id, str) or not re.match(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid resume_id.")
    if schema_version is None:
        schema_version = "v1"
    if not isinstance(schema_version, str) or schema_version not in ("v1",):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Unsupported schema_version.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.")

    # ---- workspace checks + quotas (job creation with status queued must be rejected)
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Workspace is not active; job creation is not allowed.", workspace_status=ws.get("status"))

    resumes = _ensure_list(_load("resumes.json"))
    resume = next((r for r in resumes if r.get("id") == resume_id), None)
    if not resume:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "Resume not found.")
    if resume.get("workspace_id") != workspace_id:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "Resume not found.")

    jobs = _ensure_list(_load("processing_jobs.json"))

    # idempotency reuse
    if idempotency_key is not None and idempotency_key.strip():
        existing = next((j for j in jobs if j.get("workspace_id") == workspace_id and j.get("tool_name") == "parse_resume" and j.get("idempotency_key") == idempotency_key), None)
        if existing:
            _log("ok", None, workspace_id_used=workspace_id, job_id=existing.get("id"))
            return {"job": existing, "resume": resume}

    # quota counting (calendar month by job created_at)
    mk = _month_key(now_dt)
    month_jobs = [j for j in jobs if j.get("workspace_id") == workspace_id and _job_month(j) == mk]
    used_jobs = len(month_jobs)
    used_tokens = 0
    for j in month_jobs:
        pt = j.get("prompt_tokens")
        ct = j.get("completion_tokens")
        if isinstance(pt, int) and pt >= 0:
            used_tokens += pt
        if isinstance(ct, int) and ct >= 0:
            used_tokens += ct

    monthly_job_limit = ws.get("monthly_job_limit")
    monthly_token_limit = ws.get("monthly_token_limit")
    if not isinstance(monthly_job_limit, int) or monthly_job_limit < 0:
        monthly_job_limit = 0
    if not isinstance(monthly_token_limit, int) or monthly_token_limit < 0:
        monthly_token_limit = 0

    projected_tokens = 1200  # deterministic server estimate for parse
    if used_jobs + 1 > monthly_job_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Monthly job limit exceeded.", monthly_job_limit=monthly_job_limit, used_jobs=used_jobs)
    if used_tokens + projected_tokens > monthly_token_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Monthly token limit would be exceeded by this request.", monthly_token_limit=monthly_token_limit, used_tokens=used_tokens, projected_tokens=projected_tokens)

    # ---- business rule: parse_resume must not overwrite existing parsed data
    if resume.get("parsed_resume_json") is not None:
        # still create a job row; job will fail with a clear reason
        job = {
            "id": _gen_id("rmz_job_"),
            "workspace_id": workspace_id,
            "resume_id": resume_id,
            "linkedin_profile_id": None,
            "tool_name": "parse_resume",
            "status": "queued",
            "idempotency_key": idempotency_key,
            "input_json": {"resume_id": resume_id, "schema_version": schema_version},
            "output_json": None,
            "error_code": None,
            "error_message": None,
            "cost_usd": 0.0,
            "prompt_tokens": 0,
            "completion_tokens": 0,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(job)
        _save("processing_jobs.json", jobs)

        # progress through lifecycle to failed
        job["status"] = "running"
        job["started_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)

        job["status"] = "failed"
        job["finished_at"] = now
        job["updated_at"] = now
        job["error_code"] = "PARSE_NOT_ALLOWED"
        job["error_message"] = "Parsed resume already exists; use update_parsed_resume or apply_ats_suggestions to modify parsed data."
        _save("processing_jobs.json", jobs)

        _log("ok", None, workspace_id_used=workspace_id, job_id=job.get("id"))
