    job["finished_at"] = now
    job["updated_at"] = now
    job["output_json"] = {"resume_id": resume_id, "parsed_schema_version": "v1"}
    _save("processing_jobs.json", jobs)

    _log("ok", None, workspace_id_used=workspace_id, job_id=job.get("id"))
