def generate_resume(workspace_id, resume_id, format, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, workspace_id=None, job_id=None, idempotency_key=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rmz_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "job_id": job_id,
            "idempotency_key": idempotency_key,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex.upper()

    def _month_prefix(ts_iso):
        try:
            dt = datetime.datetime.fromisoformat(ts_iso.replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime.utcnow()
        return f"{dt.year:04d}-{dt.month:02d}"

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad workspace_id")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(resume_id, str) or not re.match(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad resume_id")
        return _err("VALIDATION_ERROR", "resume_id is malformed")
    if not isinstance(format, str) or format not in ("text", "markdown", "html", "docx", "pdf", "json"):
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad format")
        return _err("VALIDATION_ERROR", "format must be one of: text, markdown, html, docx, pdf, json")

    jobs = _load("processing_jobs.json")
    if idempotency_key is not None:
        if not isinstance(idempotency_key, str) or not idempotency_key.strip():
            _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="bad idempotency_key")
            return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
        for j in jobs:
            if isinstance(j, dict) and j.get("workspace_id") == workspace_id and j.get("tool_name") == "generate_resume" and j.get("idempotency_key") == idempotency_key:
                resumes = _load("resumes.json")
                r = next((x for x in resumes if isinstance(x, dict) and x.get("id") == j.get("resume_id")), None)
                _log("generate_resume", "ok", workspace_id=workspace_id, job_id=j.get("id"), idempotency_key=idempotency_key, detail="idempotent replay")
                return {"resume": r, "job": j}

    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp:
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="workspace not found")
        return _err("NOT_FOUND", "workspace not found")
    if wsp.get("status") in ("suspended", "deleted"):
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="workspace not active")
        return _err("UNAUTHORIZED", "workspace is not active")

    resumes = _load("resumes.json")
    r = next((x for x in resumes if isinstance(x, dict) and x.get("id") == resume_id and x.get("workspace_id") == workspace_id), None)
    if not r:
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="resume not found")
        return _err("NOT_FOUND", "resume not found")
    if r.get("status") == "deleted":
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="resume deleted")
        return _err("INVALID_TRANSITION", "cannot generate from a deleted resume")

    # quota checks (token-heavy)
    month = _month_prefix(now)
    month_jobs = 0
    month_tokens = 0
    for j in jobs:
        if not isinstance(j, dict) or j.get("workspace_id") != workspace_id:
            continue
        created_at = j.get("created_at") or ""
        if isinstance(created_at, str) and created_at.startswith(month):
            month_jobs += 1
            month_tokens += int(j.get("prompt_tokens") or 0) + int(j.get("completion_tokens") or 0)
    limit_jobs = int(wsp.get("monthly_job_limit") or 0)
    limit_tokens = int(wsp.get("monthly_token_limit") or 0)
    projected_tokens = 1400 if format in ("docx", "pdf") else 1100
    if month_jobs + 1 > limit_jobs:
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="monthly job limit exceeded")
        return _err("QUOTA_EXCEEDED", "monthly job limit exceeded", limit=limit_jobs)
    if month_tokens + projected_tokens > limit_tokens:
        _log("generate_resume", "error", workspace_id=workspace_id, idempotency_key=idempotency_key, detail="monthly token limit exceeded (projected)")
        return _err("QUOTA_EXCEEDED", "monthly token limit exceeded", limit=limit_tokens)

    # create job queued
    job_id = _gen_id("rmz_job_")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": resume_id,
        "linkedin_profile_id": None,
        "tool_name": "generate_resume",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {"workspace_id": workspace_id, "resume_id": resume_id, "format": format},
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.05 if format in ("text", "markdown") else 0.08 if format in ("html", "json") else 0.12,
        "prompt_tokens": int(projected_tokens * 0.65),
        "completion_tokens": int(projected_tokens * 0.35),
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    # queued -> running
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # source preference: parsed if present else raw_text
    parsed = r.get("parsed_resume_json")
    raw = r.get("raw_text") if isinstance(r.get("raw_text"), str) else ""
    if parsed is None and (not isinstance(raw, str) or not raw.strip()):
        job["status"] = "failed"
        job["error_code"] = "NO_INPUT"
        job["error_message"] = "No parsed data or extracted text available to generate from."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)
        _log("generate_resume", "error", workspace_id=workspace_id, job_id=job_id, idempotency_key=idempotency_key, detail="no input")
        return _err("CONFLICT", "resume has no parsed data or extracted text to generate from", job=job)

    # Generate deterministic artifact text
    title = r.get("title") or "Resume"
    if parsed is not None and isinstance(parsed, dict):
        base = f"{title}\n\nMODERNIZED ({format})\n\nSummary: {parsed.get('summary','')}\n"
        highlights = parsed.get("highlights") if isinstance(parsed.get("highlights"), list) else []
        if highlights:
            base += "Highlights:\n" + "\n".join([f"- {str(h)[:200]}" for h in highlights[:8]]) + "\n"
    else:
        excerpt = raw.strip().splitlines()
        excerpt = "\n".join(excerpt[:20])
        base = f"{title}\n\nMODERNIZED ({format})\n\n{excerpt}\n"

    if format == "json":
        generated_text = json.dumps({"title": title, "content": base}, ensure_ascii=False, indent=2)
    elif format == "html":
        generated_text = "<html><body><pre>" + base.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;") + "</pre></body></html>"
    else:
        generated_text = base

    # Update resume fields (allowed by rule)
    r["latest_generated_resume_text"] = generated_text
    r["latest_generated_format"] = format
    # status can go ready->processing->ready
    if r.get("status") in ("draft", "ready", "archived", "processing"):
        r["status"] = "processing"
        r["updated_at"] = now
        _save("resumes.json", resumes)
        r["status"] = "ready"
        r["updated_at"] = now
    else:
        job["status"] = "failed"
        job["error_code"] = "INVALID_RESUME_STATUS"
        job["error_message"] = f"Resume status {r.get('status')} cannot be generated."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)
        _log("generate_resume", "error", workspace_id=workspace_id, job_id=job_id, idempotency_key=idempotency_key, detail="invalid resume status")
        return _err("INVALID_TRANSITION", "resume cannot transition for generation", current_status=r.get("status"), job=job)

    job["status"] = "succeeded"
    job["output_json"] = {"resume_id": resume_id, "format": format, "length": len(generated_text)}
    job["finished_at"] = now
    job["updated_at"] = now

    _save("resumes.json", resumes)
    _save("processing_jobs.json", jobs)

    _log("generate_resume", "ok", workspace_id=workspace_id, job_id=job_id, idempotency_key=idempotency_key)
    return {"resume": r, "job": job}

