def skill_gap_analyzer(workspace_id, resume_id, job_description, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, workspace_id_used=None, job_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "rmz_req_" + hashlib.sha1(f"{now}|skill_gap_analyzer|{status}|{workspace_id_used}|{job_id}|{len(logs)}".encode("utf-8")).hexdigest()[:20].upper(),
                "endpoint": "skill_gap_analyzer",
                "workspace_id": workspace_id_used,
                "job_id": job_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _valid_id(pattern, s):
        return isinstance(s, str) and re.match(pattern, s or "") is not None

    # Validate inputs
    if not _valid_id(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log_call("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if not _valid_id(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
        _log_call("error", workspace_id, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid resume_id format.", field="resume_id")
    if not isinstance(job_description, str) or not job_description.strip():
        _log_call("error", workspace_id, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "job_description is required and must be non-empty.", field="job_description")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log_call("error", workspace_id, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.", field="idempotency_key")

    # Load store
    workspaces = _load("workspaces.json")
    resumes = _load("resumes.json")
    jobs = _load("processing_jobs.json")

    if not isinstance(workspaces, list) or not isinstance(resumes, list) or not isinstance(jobs, list):
        _log_call("error", workspace_id, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unavailable.")

    wsp = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not wsp:
        _log_call("error", workspace_id, None, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if wsp.get("status") in ("suspended", "deleted"):
        _log_call("error", workspace_id, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=wsp.get("status"))

    rsm = next((r for r in resumes if r.get("id") == resume_id and r.get("workspace_id") == workspace_id), None)
    if not rsm:
        _log_call("error", workspace_id, None, "NOT_FOUND")
        return _err("NOT_FOUND", "Resume not found in workspace.", resume_id=resume_id, workspace_id=workspace_id)
    if rsm.get("status") == "deleted":
        _log_call("error", workspace_id, None, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot analyze a deleted resume.", resume_status="deleted")

    # Idempotency: unique(workspace_id, tool_name, idempotency_key) where idempotency_key is not null
    if idempotency_key:
        existing = next(
            (j for j in jobs if j.get("workspace_id") == workspace_id and j.get("tool_name") == "skill_gap_analyzer" and j.get("idempotency_key") == idempotency_key),
            None,
        )
        if existing:
            _log_call("ok", workspace_id, existing.get("id"), None)
            return {"job": existing}

    # Quotas: monthly_job_limit and monthly_token_limit enforced at queued creation
    def _month_start(dt):
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    try:
        dt_now = datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
    except Exception:
        dt_now = datetime.datetime.utcnow().replace(microsecond=0)
    month_start = _month_start(dt_now)
    month_start_iso = month_start.isoformat() + "Z"

    def _parse_ts(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                return datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ")
        except Exception:
            return None
        return None

    month_jobs = 0
    month_tokens = 0
    for j in jobs:
        if j.get("workspace_id") != workspace_id:
            continue
        cts = _parse_ts(j.get("created_at"))
        if not cts or cts < month_start:
            continue
        # count any job created this month (queued/running/succeeded/failed/cancelled)
        month_jobs += 1
        month_tokens += int(j.get("prompt_tokens") or 0) + int(j.get("completion_tokens") or 0)

    limit_jobs = int(wsp.get("monthly_job_limit") or 0)
    if month_jobs >= limit_jobs:
        _log_call("error", workspace_id, None, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly job limit exceeded.", monthly_job_limit=limit_jobs, month_jobs=month_jobs, month_start=month_start_iso)

    # Projected tokens: heuristic based on inputs; enforce vs monthly_token_limit
    def _estimate_tokens(text):
        # crude: ~4 chars/token; include some overhead
        if not isinstance(text, str):
            return 0
        return max(1, int(len(text) / 4) + 50)

    resume_text = rsm.get("raw_text") or ""
    parsed = rsm.get("parsed_resume_json")
    parsed_text_hint = ""
    if isinstance(parsed, dict):
        # small textual projection of parsed fields to approximate analysis cost
        for k in ("summary", "headline", "title"):
            v = parsed.get(k)
            if isinstance(v, str):
                parsed_text_hint += v + "\n"
        skills = parsed.get("skills")
        if isinstance(skills, list):
            parsed_text_hint += " ".join([str(x) for x in skills[:200]]) + "\n"
    prompt_est = _estimate_tokens(job_description) + _estimate_tokens(resume_text) + _estimate_tokens(parsed_text_hint)
    completion_est = int(prompt_est * 0.25)

    limit_tokens = int(wsp.get("monthly_token_limit") or 0)
    if month_tokens + prompt_est + completion_est > limit_tokens:
        _log_call("error", workspace_id, None, "QUOTA_EXCEEDED")
        return _err(
            "QUOTA_EXCEEDED",
            "Monthly token limit would be exceeded by this request.",
            monthly_token_limit=limit_tokens,
            month_tokens=month_tokens,
            projected_additional_tokens=prompt_est + completion_est,
            month_start=month_start_iso,
        )

    # Create job queued then run synchronously to completion (progress lifecycle correctly)
    def _new_id(prefix, rows):
        return prefix + hashlib.sha1(f"{prefix}|{now}|{len(rows)}|{os.getpid()}".encode("utf-8")).hexdigest()[:20].upper()

    job_id = _new_id("rmz_job_", jobs)
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": resume_id,
        "linkedin_profile_id": None,
        "tool_name": "skill_gap_analyzer",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {
            "workspace_id": workspace_id,
            "resume_id": resume_id,
            "job_description": job_description,
        },
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": int(prompt_est),
        "completion_tokens": int(completion_est),
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    # Move to running
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # Perform simple skill gap analysis
    def _tokenize_words(s):
        return set(re.findall(r"[A-Za-z][A-Za-z0-9\+\#\.\-]{1,}", s.lower())) if isinstance(s, str) else set()

    # extract candidate skills from job description using a naive heuristic
    jd_words = list(re.findall(r"[A-Za-z][A-Za-z0-9\+\#\.\-]{1,}", job_description))
    common_stop = set(["the", "and", "with", "for", "you", "your", "our", "are", "will", "this", "that", "from", "have", "has", "using", "use", "as", "to", "in", "on", "of", "a", "an", "is", "be", "or"])
    candidates = []
    for w in jd_words:
        wl = w.lower()
        if wl in common_stop:
            continue
        if len(wl) <= 2:
            continue
        # prefer tech-like tokens
        if any(ch in wl for ch in ["+", "#", ".", "-"]) or wl in ("sql", "aws", "gcp", "azure", "docker", "kubernetes", "python", "java", "javascript", "typescript", "react", "node", "golang", "rust", "scala", "spark", "hadoop", "ml", "ai"):
            candidates.append(w)
        elif w[0].isupper():
            candidates.append(w)

    # de-dupe preserving order
    seen = set()
    jd_skillish = []
    for c in candidates:
        cl = c.lower()
        if cl not in seen:
            seen.add(cl)
            jd_skillish.append(c)

    resume_corpus = ""
    if isinstance(resume_text, str) and resume_text.strip():
        resume_corpus += resume_text + "\n"
    if isinstance(parsed, dict):
        resume_corpus += json.dumps(parsed, ensure_ascii=False)
    resume_words = _tokenize_words(resume_corpus)

    matched = []
    missing = []
    for s in jd_skillish[:200]:
        sl = s.lower()
        if sl in resume_words:
            matched.append(s)
        else:
            missing.append(s)

    recommendations = []
    for s in missing[:25]:
        recommendations.append(
            {
                "skill": s,
                "suggestion": f"Add evidence of {s} in your experience bullets (projects, tools used, outcomes).",
            }
        )

    output = {
        "matched_skills": matched[:100],
        "missing_skills": missing[:100],
        "recommendations": recommendations,
        "notes": {
            "method": "heuristic_token_match",
            "job_description_skills_considered": len(jd_skillish),
        },
    }

    job["output_json"] = output
    job["status"] = "succeeded"
    job["finished_at"] = now
    job["updated_at"] = now
    # cost estimate
    job["cost_usd"] = round((job["prompt_tokens"] + job["completion_tokens"]) * 0.000002, 6)
    _save("processing_jobs.json", jobs)

    _log_call("ok", workspace_id, job_id, None)
    return {"job": job}

