            return 0
        return max(1, int(len(text) / 4) + 40)

    resume_text = rsm.get("raw_text") or ""
    parsed = rsm.get("parsed_resume_json")
    parsed_hint = ""
    if isinstance(parsed, dict):
        parsed_hint = json.dumps(parsed, ensure_ascii=False)[:8000]

    prompt_est = _estimate_tokens(resume_text) + _estimate_tokens(parsed_hint) + _estimate_tokens(job_description or "")
    completion_est = int(max(60, prompt_est * 0.2))

    limit_tokens = int(wsp.get("monthly_token_limit") or 0)
    if month_tokens + prompt_est + completion_est > limit_tokens:
