    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # Heuristic scoring signals
    raw = (resume_text or "").strip()
    has_raw = bool(raw)
    has_parsed = isinstance(parsed, dict) and len(parsed) > 0
    gen_text = (rsm.get("latest_generated_resume_text") or "").strip()
    has_generated = bool(gen_text)

    length_score = 0
    if has_raw:
        n = len(raw)
        if n < 800:
            length_score = 40
        elif n < 2000:
            length_score = 70
        elif n < 6000:
            length_score = 85
        else:
            length_score = 75

    section_keywords = ["experience", "education", "skills", "projects", "summary"]
    raw_lower = raw.lower() if has_raw else ""
    section_hits = sum(1 for k in section_keywords if k in raw_lower)
    structure_score = min(100, section_hits * 20) if has_raw else (60 if has_parsed else 30)

    bullet_score = 0
    if has_raw:
        bullets = raw.count("\n-") + raw.count("\n•")
        bullet_score = min(100, int(bullets * 5))
    elif has_parsed:
        bullet_score = 70

    jd_fit = None
    if isinstance(job_description, str) and job_description.strip():
        def _words(s):
            import re
            return set(re.findall(r"[A-Za-z][A-Za-z0-9\+\#\.\-]{1,}", s.lower()))
        jd_words = _words(job_description)
        resume_words = _words(raw + "\n" + (json.dumps(parsed, ensure_ascii=False) if has_parsed else "") + "\n" + gen_text)
