            overlap = len(jd_words & resume_words) / max(1, len(jd_words))
            jd_fit = int(max(0, min(100, overlap * 100)))

    ats_score = int(round((structure_score * 0.5 + bullet_score * 0.3 + length_score * 0.2)))
