    overall = int(round((quality_score * 0.65 + ats_score * 0.35))) if jd_fit is None else int(round((quality_score * 0.45 + ats_score * 0.25 + jd_fit * 0.30)))

    signals = {
        "has_raw_text": has_raw,
        "has_parsed_resume_json": has_parsed,
        "has_latest_generated_resume_text": has_generated,
        "section_hits": section_hits,
    }

    output = {
        "overall_score": overall,
        "quality_score": quality_score,
        "ats_readiness_score": ats_score,
        "job_fit_score": jd_fit,
        "signals": signals,
        "breakdown": {
            "length_score": length_score,
            "structure_score": structure_score,
            "bullet_score": bullet_score,
        },
        "notes": {"method": "heuristic"},
    }

    job["output_json"] = output
    job["status"] = "succeeded"
    job["finished_at"] = now
    job["updated_at"] = now
    job["cost_usd"] = round((job["prompt_tokens"] + job["completion_tokens"]) * 0.000002, 6)
    _save("processing_jobs.json", jobs)

    _log_call("ok", workspace_id, job_id, None)
    return {"job": job}

