            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x): return x if isinstance(x, list) else []

    def _log(status, error_code=None, workspace_id_used=None, job_id=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "rmz_req_" + uuid.uuid4().hex.upper()[:19],
            "timestamp": now,
            "endpoint": "extract_linkedin_profile_api",
            "workspace_id": workspace_id_used,
            "job_id": job_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    def _month_key(dt): return dt.strftime("%Y-%m")

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _current_month_job_count(jobs, ws_id):
        mk = _month_key(now_dt)
        c = 0
        for j in jobs:
            if j.get("workspace_id") != ws_id:
                continue
            d = _parse_iso(j.get("created_at") or j.get("updated_at") or j.get("started_at") or j.get("finished_at"))
            if d is None:
                continue
            if d.strftime("%Y-%m") == mk:
                c += 1
        return c

    def _current_month_token_sum(jobs, ws_id):
        mk = _month_key(now_dt)
        s = 0
        for j in jobs:
            if j.get("workspace_id") != ws_id:
                continue
            d = _parse_iso(j.get("created_at") or j.get("updated_at") or j.get("started_at") or j.get("finished_at"))
            if d is None:
                continue
            if d.strftime("%Y-%m") == mk:
                pt = j.get("prompt_tokens") if isinstance(j.get("prompt_tokens"), int) else 0
                ct = j.get("completion_tokens") if isinstance(j.get("completion_tokens"), int) else 0
                s += max(0, pt) + max(0, ct)
        return s

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:19]

    # ---- validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if linkedin_profile_id is not None and (not isinstance(linkedin_profile_id, str) or not re.match(r"^rmz_lnk_[0-9A-Z]{18,}$", linkedin_profile_id)):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid linkedin_profile_id.")
    if profile_url is not None and not isinstance(profile_url, str):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "profile_url must be a string when provided.")
    if public_identifier is not None and not isinstance(public_identifier, str):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "public_identifier must be a string when provided.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.")
    if (linkedin_profile_id is None) and (not profile_url) and (not public_identifier):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Provide linkedin_profile_id or profile_url/public_identifier.")

    # ---- load workspace, enforce workspace status
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") in ("suspended", "deleted"):
        _log("error", "UNAUTHORIZED", workspace_id_used=workspace_id)
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # ---- idempotency: reuse existing job if present
    jobs = _ensure_list(_load("processing_jobs.json"))
    if idempotency_key:
        existing = next((j for j in jobs if j.get("workspace_id") == workspace_id and j.get("tool_name") == "extract_linkedin_profile_api" and j.get("idempotency_key") == idempotency_key), None)
        if existing:
            # Return job and referenced linkedin_profile if possible
            lps = _ensure_list(_load("linkedin_profiles.json"))
            lp = None
            lp_id = existing.get("linkedin_profile_id")
            if isinstance(lp_id, str):
                lp = next((p for p in lps if p.get("id") == lp_id and p.get("workspace_id") == workspace_id), None)
            _log("ok", None, workspace_id_used=workspace_id, job_id=existing.get("id"))
            return {"job": existing, "linkedin_profile": lp, "reused": True}

    # ---- resolve/create linkedin profile target (do NOT refuse if provided id doesn't exist; create it)
    lps = _ensure_list(_load("linkedin_profiles.json"))
    target = None

    if linkedin_profile_id:
        target = next((p for p in lps if p.get("id") == linkedin_profile_id and p.get("workspace_id") == workspace_id), None)
        if not target:
            # Create record with given id to populate (accept caller-provided id)
            target = {
                "id": linkedin_profile_id,
                "workspace_id": workspace_id,
                "status": "pending",
                "method": "api",
                "profile_url": profile_url if isinstance(profile_url, str) and profile_url.strip() else None,
                "public_identifier": public_identifier if isinstance(public_identifier, str) and public_identifier.strip() else None,
                "raw_profile_json": None,
                "normalized_resume_json": None,
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now
            }
            lps.append(target)
    else:
        # Try find by profile_url then public_identifier
        if isinstance(profile_url, str) and profile_url.strip():
            target = next((p for p in lps if p.get("workspace_id") == workspace_id and p.get("profile_url") == profile_url and p.get("status") != "deleted"), None)
        if (not target) and isinstance(public_identifier, str) and public_identifier.strip():
            target = next((p for p in lps if p.get("workspace_id") == workspace_id and p.get("public_identifier") == public_identifier and p.get("status") != "deleted"), None)
        if not target:
            target = {
                "id": _gen_id("rmz_lnk_"),
                "workspace_id": workspace_id,
                "status": "pending",
                "method": "api",
                "profile_url": profile_url if isinstance(profile_url, str) and profile_url.strip() else None,
                "public_identifier": public_identifier if isinstance(public_identifier, str) and public_identifier.strip() else None,
                "raw_profile_json": None,
                "normalized_resume_json": None,
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now
            }
            lps.append(target)

    # Unique(workspace_id, profile_url) where profile_url not null
    if target.get("profile_url"):
        conflict = next((p for p in lps if p is not target and p.get("workspace_id") == workspace_id and p.get("profile_url") == target.get("profile_url") and p.get("status") != "deleted"), None)
        if conflict:
            # Prefer existing record (idempotent-ish): use conflict instead of creating duplicate
            target = conflict

    # ---- enforce quotas BEFORE creating a queued job
    monthly_job_limit = ws.get("monthly_job_limit")
    monthly_token_limit = ws.get("monthly_token_limit")
    if not isinstance(monthly_job_limit, int) or monthly_job_limit < 0:
        monthly_job_limit = 0
    if not isinstance(monthly_token_limit, int) or monthly_token_limit < 0:
        monthly_token_limit = 0

    used_jobs = _current_month_job_count(jobs, workspace_id)
    if used_jobs + 1 > monthly_job_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Workspace monthly_job_limit exceeded.", limit=monthly_job_limit, used=used_jobs)

    # Projected tokens (rough deterministic estimate; API extraction is light)
    projected_prompt = 300
    projected_completion = 100
    used_tokens = _current_month_token_sum(jobs, workspace_id)
    if used_tokens + projected_prompt + projected_completion > monthly_token_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Workspace monthly_token_limit would be exceeded.", limit=monthly_token_limit, used=used_tokens, projected=projected_prompt + projected_completion)

    # ---- create processing job with queued status
    job_id = _gen_id("rmz_job_")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": None,
        "linkedin_profile_id": target.get("id"),
        "tool_name": "extract_linkedin_profile_api",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {
            "workspace_id": workspace_id,
            "linkedin_profile_id": target.get("id"),
            "profile_url": profile_url,
            "public_identifier": public_identifier,
            "method": "api"
        },
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": projected_prompt,
        "completion_tokens": projected_completion,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    # ---- advance job lifecycle (queued -> running -> succeeded) and linkedin profile (pending -> processing -> ready)
    # Update LinkedIn profile status transitions
    transitions_lp = {"pending": ["processing", "failed", "deleted"], "processing": ["ready", "failed", "deleted"], "ready": ["deleted"], "failed": ["pending", "deleted"], "deleted": []}
    if target.get("status") not in transitions_lp:
        target["status"] = "pending"
    # pending -> processing
    if "processing" in transitions_lp.get(target["status"], []):
        target["status"] = "processing"
        target["updated_at"] = now
    elif target["status"] != "processing":
        # If in ready/failed, keep as-is but still proceed (re-extraction allowed by creating job)
        pass

    # queued -> running
    transitions_job = {"queued": ["running", "cancelled"], "running": ["succeeded", "failed", "cancelled"], "succeeded": [], "failed": [], "cancelled": []}
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now

    # "Extract": store deterministic raw payload
    seed = (target.get("profile_url") or "") + "|" + (target.get("public_identifier") or "") + "|" + target.get("id")
    h = hashlib.sha256(seed.encode("utf-8")).hexdigest()
    raw_profile = {
        "source": "linkedin_api",
        "profile_url": target.get("profile_url"),
        "public_identifier": target.get("public_identifier"),
        "extracted_at": now,
        "profile_hash": h,
        "data": {
            "headline": "Imported via API",
            "summary": None,
            "positions": [],
            "education": [],
            "skills": []
        }
    }
    target["raw_profile_json"] = raw_profile
    target["error_code"] = None
    target["error_message"] = None

    # processing -> ready
    if "ready" in transitions_lp.get(target.get("status"), []):
        target["status"] = "ready"
    target["updated_at"] = now

    # running -> succeeded
    job["status"] = "succeeded"
    job["finished_at"] = now
    job["updated_at"] = now
    job["output_json"] = {"linkedin_profile_id": target.get("id"), "status": target.get("status")}

    # ---- persist
    # ensure lps contains the updated target object row
    # if we switched to conflict record earlier, ensure it exists and is updated
    found_idx = None
    for i, p in enumerate(lps):
        if p.get("id") == target.get("id"):
            found_idx = i
            break
    if found_idx is None:
        lps.append(target)
    else:
        lps[found_idx] = target

    _save("linkedin_profiles.json", lps)
    _save("processing_jobs.json", jobs)

    _log("ok", None, workspace_id_used=workspace_id, job_id=job_id)
    return {"job": job, "linkedin_profile": target, "reused": False}

