        if (not target) and isinstance(public_identifier, str) and public_identifier.strip():
            target = next((p for p in lps if p.get("workspace_id") == workspace_id and p.get("public_identifier") == public_identifier and p.get("status") != "deleted"), None)
        if not target:
            target = {
                "id": _gen_id("rmz_lnk_"),
                "workspace_id": workspace_id,
                "status": "pending",
                "method": method,
                "profile_url": profile_url if isinstance(profile_url, str) and profile_url.strip() else None,
                "public_identifier": public_identifier if isinstance(public_identifier, str) and public_identifier.strip() else None,
                "raw_profile_json": None,
                "normalized_resume_json": None,
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now
            }
            lps.append(target)

    # unique(workspace_id, profile_url) where profile_url not null
    if target.get("profile_url"):
        conflict = next((p for p in lps if p is not target and p.get("workspace_id") == workspace_id and p.get("profile_url") == target.get("profile_url") and p.get("status") != "deleted"), None)
        if conflict:
            target = conflict

    # ---- quotas before creating queued job
    monthly_job_limit = ws.get("monthly_job_limit")
    monthly_token_limit = ws.get("monthly_token_limit")
    if not isinstance(monthly_job_limit, int) or monthly_job_limit < 0:
        monthly_job_limit = 0
    if not isinstance(monthly_token_limit, int) or monthly_token_limit < 0:
        monthly_token_limit = 0

    used_jobs = _current_month_job_count(jobs, workspace_id)
    if used_jobs + 1 > monthly_job_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Workspace monthly_job_limit exceeded.", limit=monthly_job_limit, used=used_jobs)

    # Projected tokens
    projected_prompt = 250
    projected_completion = 80
    used_tokens = _current_month_token_sum(jobs, workspace_id)
    if used_tokens + projected_prompt + projected_completion > monthly_token_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Workspace monthly_token_limit would be exceeded.", limit=monthly_token_limit, used=used_tokens, projected=projected_prompt + projected_completion)

    # ---- create job queued
    job_id = _gen_id("rmz_job_")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": None,
        "linkedin_profile_id": target.get("id"),
        "tool_name": "extract_linkedin_profile",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {
            "workspace_id": workspace_id,
            "linkedin_profile_id": target.get("id"),
            "profile_url": profile_url,
            "public_identifier": public_identifier,
            "method": method
        },
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": projected_prompt,
        "completion_tokens": projected_completion,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    # ---- transitions: linkedin pending->processing->ready and job queued->running->succeeded
    transitions_lp = {"pending": ["processing", "failed", "deleted"], "processing": ["ready", "failed", "deleted"], "ready": ["deleted"], "failed": ["pending", "deleted"], "deleted": []}
    if target.get("status") not in transitions_lp:
        target["status"] = "pending"
    target["method"] = method
    if "processing" in transitions_lp.get(target["status"], []):
        target["status"] = "processing"
    target["updated_at"] = now

    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now

    seed = (target.get("profile_url") or "") + "|" + (target.get("public_identifier") or "") + "|" + target.get("id") + "|" + method
    h = hashlib.sha256(seed.encode("utf-8")).hexdigest()
    target["raw_profile_json"] = {
        "source": f"linkedin_{method}",
        "profile_url": target.get("profile_url"),
        "public_identifier": target.get("public_identifier"),
        "extracted_at": now,
        "profile_hash": h,
        "data": {"note": "Extracted (simulated) via non-API method", "positions": [], "education": [], "skills": []}
    }
    target["error_code"] = None
    target["error_message"] = None

    if "ready" in transitions_lp.get(target.get("status"), []):
        target["status"] = "ready"
    target["updated_at"] = now

    job["status"] = "succeeded"
    job["finished_at"] = now
    job["updated_at"] = now
    job["output_json"] = {"linkedin_profile_id": target.get("id"), "status": target.get("status")}

    # ---- persist
    found_idx = None
    for i, p in enumerate(lps):
        if p.get("id") == target.get("id"):
            found_idx = i
            break
    if found_idx is None:
        lps.append(target)
    else:
        lps[found_idx] = target

    _save("linkedin_profiles.json", lps)
    _save("processing_jobs.json", jobs)

    _log("ok", None, workspace_id_used=workspace_id, job_id=job_id)
    return {"job": job, "linkedin_profile": target, "reused": False}

def update_resume_for_job(workspace_id, resume_id, idempotency_key=None, job_title=None, job_description=None, company_name=None, location=None, seniority=None, output_format=None, include_change_log=None, **_extra):
    import json, os, datetime, time, re, hashlib, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    def _hash_words(text):
        words = re.findall(r"[A-Za-z][A-Za-z0-9\-\+#\.]{1,}", text.lower() if text else "")
        return words

    def _estimate_tokens(*parts):
        s = " ".join([p for p in parts if isinstance(p, str) and p.strip()])
        if not s:
            return 200  # baseline
        # rough: 1 token ~ 4 chars
        return max(50, int(len(s) / 4) + 50)

    def _month_key(ts_iso):
        try:
            dt = datetime.datetime.fromisoformat(ts_iso.replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime.utcnow()
        return dt.strftime("%Y-%m")

    def _record_request(status, used_workspace_id, job_id=None, err=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": _gen_id("rmz_req_"),
            "tool_name": "update_resume_for_job",
            "workspace_id": used_workspace_id,
            "job_id": job_id,
            "status": status,
            "error": err,
            "latency_ms": latency_ms,
            "created_at": now
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- validation
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _record_request("error", workspace_id if isinstance(workspace_id, str) else None, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(resume_id, str) or not re.match(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "resume_id is invalid", field="resume_id")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a string", field="idempotency_key")
    if job_title is not None and not isinstance(job_title, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "job_title must be a string", field="job_title")
    if job_description is not None and not isinstance(job_description, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "job_description must be a string", field="job_description")
    if company_name is not None and not isinstance(company_name, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "company_name must be a string", field="company_name")
    if location is not None and not isinstance(location, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "location must be a string", field="location")
    if seniority is not None:
        allowed = {"intern","junior","mid","senior","lead","manager","director","vp","cxo"}
        if not isinstance(seniority, str) or seniority not in allowed:
            _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "seniority is invalid", field="seniority", allowed=sorted(list(allowed)))
    if output_format is not None:
        allowed = {"text","markdown","html","docx","pdf","json"}
        if not isinstance(output_format, str) or output_format not in allowed:
            _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "output_format is invalid", field="output_format", allowed=sorted(list(allowed)))
    if include_change_log is not None and not isinstance(include_change_log, bool):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_change_log must be a boolean", field="include_change_log")

    workspaces = _load("workspaces.json")
    resumes = _load("resumes.json")
    jobs = _load("processing_jobs.json")

    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(resumes, list): resumes = []
    if not isinstance(jobs, list): jobs = []

    wsp = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not wsp:
        _record_request("error", workspace_id, err={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)
    if wsp.get("status") in ("suspended", "deleted"):
        _record_request("error", workspace_id, err={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "workspace is not allowed to create jobs in current status", status=wsp.get("status"))

    rsm = next((r for r in resumes if r.get("id") == resume_id and r.get("workspace_id") == workspace_id), None)
    if not rsm or rsm.get("status") == "deleted":
        _record_request("error", workspace_id, err={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "resume not found", resume_id=resume_id)

    # Idempotency: unique(workspace_id, tool_name, idempotency_key)
    if idempotency_key:
        existing = next((j for j in jobs if j.get("workspace_id") == workspace_id and j.get("tool_name") == "update_resume_for_job" and j.get("idempotency_key") == idempotency_key), None)
        if existing:
            _record_request("ok", workspace_id, job_id=existing.get("id"))
            return {
                "job": existing,
                "resume_id": resume_id,
                "output": existing.get("output_json")
            }

    # Quota checks (monthly jobs + projected tokens)
    month = _month_key(now)
    month_jobs = [j for j in jobs if j.get("workspace_id") == workspace_id and isinstance(j.get("created_at"), str) and _month_key(j.get("created_at")) == month]
    if len(month_jobs) >= int(wsp.get("monthly_job_limit", 0)):
        _record_request("error", workspace_id, err={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "monthly_job_limit exceeded", limit=wsp.get("monthly_job_limit"), used=len(month_jobs))

    projected_prompt = _estimate_tokens(rsm.get("raw_text") or rsm.get("latest_generated_resume_text") or "", job_title or "", job_description or "", company_name or "", location or "", seniority or "")
    projected_completion = max(100, int(projected_prompt * 0.6))
    projected_total = projected_prompt + projected_completion

    month_tokens = 0
    for j in month_jobs:
        pt = j.get("prompt_tokens")
        ct = j.get("completion_tokens")
        if isinstance(pt, int) and pt >= 0: month_tokens += pt
        if isinstance(ct, int) and ct >= 0: month_tokens += ct
    if month_tokens + projected_total > int(wsp.get("monthly_token_limit", 0)):
        _record_request("error", workspace_id, err={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "monthly_token_limit would be exceeded", limit=wsp.get("monthly_token_limit"), used=month_tokens, projected=projected_total)

    # Create job (queued)
    job_id = _gen_id("rmz_job_")
    input_json = {
        "workspace_id": workspace_id,
        "resume_id": resume_id,
        "job_title": job_title,
        "job_description": job_description,
        "company_name": company_name,
        "location": location,
        "seniority": seniority,
        "output_format": output_format or "markdown",
        "include_change_log": bool(include_change_log) if include_change_log is not None else False
    }
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": resume_id,
        "linkedin_profile_id": None,
        "tool_name": "update_resume_for_job",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": input_json,
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": 0,
        "completion_tokens": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    # Execute synchronously: queued -> running -> succeeded/failed
    def _set_job_status(j, new_status):
        transitions = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = j.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        j["status"] = new_status
        j["updated_at"] = now
        return True

    if not _set_job_status(job, "running"):
        job["error_code"] = "INVALID_TRANSITION"
        job["error_message"] = "Cannot start job from current status"
        job["finished_at"] = now
        _save("processing_jobs.json", jobs)
        _record_request("error", workspace_id, job_id=job_id, err={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "job status transition not allowed", from_status="queued", to_status="running")

    job["started_at"] = now

    # Create tailored text (deterministic-ish)
    base_text = rsm.get("latest_generated_resume_text") or rsm.get("raw_text") or ""
    if not isinstance(base_text, str):
        base_text = ""
    fmt = input_json["output_format"]

    # keyword extraction for tailoring hints
    jd_words = _hash_words(job_description or "")
    top = []
    if jd_words:
        freq = {}
        for w in jd_words:
            freq[w] = freq.get(w, 0) + 1
        top = sorted(freq.keys(), key=lambda k: (-freq[k], k))[:12]

    header = f"# Tailored Resume — {job_title or 'Target Role'}\n" if fmt in ("markdown","html") else f"Tailored Resume — {job_title or 'Target Role'}\n"
    context = []
    if company_name: context.append(f"Company: {company_name}")
    if location: context.append(f"Location: {location}")
    if seniority: context.append(f"Seniority: {seniority}")
    ctx_line = (" | ".join(context) + "\n") if context else ""

    if fmt == "html":
        generated = "<h1>Tailored Resume — {}</h1>\n<p>{}</p>\n<pre>{}</pre>\n".format(
            (job_title or "Target Role"),
            (ctx_line.strip() if ctx_line else ""),
            base_text
        )
        if top:
            generated += "<p><b>Keyword focus:</b> {}</p>\n".format(", ".join(top))
    elif fmt == "json":
        generated_obj = {
            "title": job_title or None,
            "context": {"company_name": company_name, "location": location, "seniority": seniority},
            "keyword_focus": top,
            "resume_text": base_text
        }
        generated = json.dumps(generated_obj, ensure_ascii=False, indent=2)
    else:
        generated = header + ctx_line + (base_text if base_text else "")
        if top:
            generated += ("\n\nKeyword focus: " + ", ".join(top))

    change_log = None
    if input_json["include_change_log"]:
        change_log = {
            "applied": [
                {"type": "context", "job_title": job_title, "company_name": company_name, "location": location, "seniority": seniority},
                {"type": "keyword_focus", "keywords": top}
            ],
            "notes": "This is a lightweight server-side tailoring simulation."
        }

    # Update resume fields per business rule
    rsm["latest_generated_resume_text"] = generated
    rsm["latest_generated_format"] = fmt
    rsm["updated_at"] = now
    _save("resumes.json", resumes)

    # Accounting
    job["prompt_tokens"] = projected_prompt
    job["completion_tokens"] = projected_completion
    job["cost_usd"] = round((projected_total / 1000.0) * 0.01, 6)  # nominal
    job["output_json"] = {
        "resume_id": resume_id,
        "output_format": fmt,
        "tailored_resume_text": generated if fmt in ("text","markdown","html","json") else None,
        "artifact": None if fmt in ("text","markdown","html","json") else {"format": fmt, "note": "binary artifacts not stored in this datastore"},
        "change_log": change_log
    }
    job["finished_at"] = now

    if not _set_job_status(job, "succeeded"):
        job["status"] = "failed"
        job["error_code"] = "INVALID_TRANSITION"
        job["error_message"] = "Cannot finish job from current status"
    _save("processing_jobs.json", jobs)

    _record_request("ok", workspace_id, job_id=job_id)
    return {"job": job, "resume": rsm, "output": job.get("output_json")}

