            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = j.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        j["status"] = new_status
        j["updated_at"] = now
        return True

