    job["started_at"] = now

    salutation = "Dear Hiring Manager,"
    if hiring_manager_name:
        salutation = f"Dear {hiring_manager_name},"
    elif company_name:
        salutation = f"Dear {company_name} Hiring Team,"

    body_bits = []
    if job_title and company_name:
        body_bits.append(f"I’m writing to express my interest in the {job_title} role at {company_name}.")
    elif job_title:
        body_bits.append(f"I’m writing to express my interest in the {job_title} role.")
    else:
        body_bits.append("I’m writing to express my interest in the role.")

    if job_description:
        snippet = job_description.strip().splitlines()[0]
        if len(snippet) > 180:
            snippet = snippet[:177] + "..."
        body_bits.append(f"I’m excited by the focus on {snippet}")
    body_bits.append("My background aligns well with the requirements, and I’d welcome the opportunity to discuss how I can contribute.")

    closing = "Sincerely,"
    if input_json["tone"] == "friendly":
        closing = "Best regards,"
    elif input_json["tone"] == "formal":
        closing = "Respectfully,"

    # length adjustment
    extra = ""
    if input_json["length"] == "long":
        extra = "\n\n" + "In previous roles, I delivered measurable outcomes by collaborating cross-functionally, improving processes, and communicating clearly with stakeholders. I value ownership, craftsmanship, and continuous improvement."
    elif input_json["length"] == "short":
        extra = ""

    letter_text = salutation + "\n\n" + " ".join(body_bits) + extra + "\n\n" + closing + "\n" + (rsm.get("parsed_resume_json", {}) or {}).get("contact", {}).get("name", "") if isinstance(rsm.get("parsed_resume_json"), dict) else (closing + "\n")

    output_payload = {}
    if fmt == "json":
        output_payload = {
            "format": "json",
            "salutation": salutation,
            "paragraphs": [" ".join(body_bits)] + ([extra.strip()] if extra.strip() else []),
            "closing": closing,
            "text": letter_text
        }
        out_text = json.dumps(output_payload, ensure_ascii=False, indent=2)
    elif fmt == "html":
        output_payload = {"format": "html", "html": "<p>{}</p>".format(letter_text.replace("\n\n", "</p><p>").replace("\n", "<br/>"))}
        out_text = output_payload["html"]
    elif fmt == "text":
        output_payload = {"format": "text", "text": letter_text}
        out_text = letter_text
    else:  # markdown
        output_payload = {"format": "markdown", "markdown": letter_text}
        out_text = letter_text

    # Update resume cover letter field
    rsm["latest_cover_letter_text"] = out_text
    rsm["updated_at"] = now
    _save("resumes.json", resumes)

    job["prompt_tokens"] = projected_prompt
    job["completion_tokens"] = projected_completion
    job["cost_usd"] = round((projected_total / 1000.0) * 0.01, 6)
