        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "resume_id is invalid", field="resume_id")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a string", field="idempotency_key")
    if job_title is not None and not isinstance(job_title, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "job_title must be a string", field="job_title")
    if job_description is not None and not isinstance(job_description, str):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "job_description must be a string", field="job_description")
    if include_missing_keywords is not None and not isinstance(include_missing_keywords, bool):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_missing_keywords must be a boolean", field="include_missing_keywords")
    if include_keyword_density is not None and not isinstance(include_keyword_density, bool):
        _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_keyword_density must be a boolean", field="include_keyword_density")
    if suggested_keywords_limit is not None:
        if not isinstance(suggested_keywords_limit, int):
            _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "suggested_keywords_limit must be an integer", field="suggested_keywords_limit")
        if suggested_keywords_limit < 1 or suggested_keywords_limit > 200:
            _record_request("error", workspace_id, err={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "suggested_keywords_limit out of range", field="suggested_keywords_limit", minimum=1, maximum=200)

    limit = suggested_keywords_limit if suggested_keywords_limit is not None else 50
    miss = bool(include_missing_keywords) if include_missing_keywords is not None else True
    dens = bool(include_keyword_density) if include_keyword_density is not None else False

    workspaces = _load("workspaces.json")
    resumes = _load("resumes.json")
