    if not wsp:
        _record_request("error", workspace_id, err={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)
    if wsp.get("status") in ("suspended", "deleted"):
        _record_request("error", workspace_id, err={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "workspace is not allowed to create jobs in current status", status=wsp.get("status"))

    rsm = next((r for r in resumes if r.get("id") == resume_id and r.get("workspace_id") == workspace_id), None)
    if not rsm or rsm.get("status") == "deleted":
        _record_request("error", workspace_id, err={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "resume not found", resume_id=resume_id)

    if idempotency_key:
        existing = next((j for j in jobs if j.get("workspace_id") == workspace_id and j.get("tool_name") == "ats_friendliness_check" and j.get("idempotency_key") == idempotency_key), None)
        if existing:
            _record_request("ok", workspace_id, job_id=existing.get("id"))
            return {"job": existing, "results": existing.get("output_json")}

    # quotas
    month = _month_key(now)
    month_jobs = [j for j in jobs if j.get("workspace_id") == workspace_id and isinstance(j.get("created_at"), str) and _month_key(j.get("created_at")) == month]
    if len(month_jobs) >= int(wsp.get("monthly_job_limit", 0)):
        _record_request("error", workspace_id, err={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "monthly_job_limit exceeded", limit=wsp.get("monthly_job_limit"), used=len(month_jobs))

    resume_text = rsm.get("latest_generated_resume_text") or rsm.get("raw_text") or ""
    if not isinstance(resume_text, str):
        resume_text = ""

    projected_prompt = _estimate_tokens(resume_text, target)
    projected_completion = max(100, int(projected_prompt * 0.4))
    projected_total = projected_prompt + projected_completion

    used_tokens = 0
    for j in month_jobs:
        pt = j.get("prompt_tokens"); ct = j.get("completion_tokens")
        if isinstance(pt, int) and pt >= 0: used_tokens += pt
        if isinstance(ct, int) and ct >= 0: used_tokens += ct
    if used_tokens + projected_total > int(wsp.get("monthly_token_limit", 0)):
        _record_request("error", workspace_id, err={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "monthly_token_limit would be exceeded", limit=wsp.get("monthly_token_limit"), used=used_tokens, projected=projected_total)

    # create job
    job_id = _gen_id("rmz_job_")
    input_json = {
        "workspace_id": workspace_id,
        "resume_id": resume_id,
        "target_system": target,
        "include_formatting_issues": include_fmt,
        "include_section_checks": include_sections,
        "include_score": include_sc
    }
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": resume_id,
        "linkedin_profile_id": None,
        "tool_name": "ats_friendliness_check",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": input_json,
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": 0,
        "completion_tokens": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    def _set_job_status(j, new_status):
        transitions = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = j.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        j["status"] = new_status
        j["updated_at"] = now
        return True

    if not _set_job_status(job, "running"):
        job["status"] = "failed"
        job["error_code"] = "INVALID_TRANSITION"
        job["error_message"] = "Cannot start job from current status"
        job["finished_at"] = now
        _save("processing_jobs.json", jobs)
        _record_request("error", workspace_id, job_id=job_id, err={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "job status transition not allowed", from_status="queued", to_status="running")
    job["started_at"] = now

    findings = []
    formatting_issues = []
    section_checks = []

    # simple heuristics
    if include_fmt:
        if "\t" in resume_text:
            formatting_issues.append({"type": "tab_characters", "severity": "medium", "message": "Tabs can reduce ATS parsing consistency; consider spaces."})
        if re.search(r"[•●▪]", resume_text):
            formatting_issues.append({"type": "special_bullets", "severity": "low", "message": "Non-standard bullet characters may parse poorly; consider hyphens or asterisks."})
        if re.search(r"\|", resume_text):
            formatting_issues.append({"type": "tables_or_pipes", "severity": "medium", "message": "Tables/columns can be misread by ATS; prefer single-column layout."})
        if len(max(resume_text.splitlines() or [""], key=len)) > 140:
            formatting_issues.append({"type": "very_long_lines", "severity": "low", "message": "Very long lines may wrap unpredictably; consider shorter lines."})

    parsed = rsm.get("parsed_resume_json")
    if include_sections:
        # If structured parse exists, check presence; otherwise infer from text headings.
        want = ["summary", "skills", "experience", "education"]
        present = set()
        if isinstance(parsed, dict):
            if parsed.get("summary"): present.add("summary")
            if parsed.get("skills"): present.add("skills")
            if parsed.get("experience"): present.add("experience")
            if parsed.get("education"): present.add("education")
        else:
            lower = resume_text.lower()
            if "summary" in lower: present.add("summary")
            if "skills" in lower: present.add("skills")
            if "experience" in lower or "employment" in lower: present.add("experience")
            if "education" in lower: present.add("education")
        for sec in want:
            ok = sec in present
            section_checks.append({"section": sec, "present": ok, "message": (None if ok else f"Recommended section '{sec}' not detected.")})

    # overall score
    score = None
    if include_sc:
        base = 78
        base -= 6 * len([i for i in formatting_issues if i.get("severity") in ("medium","high")])
        base -= 4 * len([s for s in section_checks if not s.get("present")])
        # adjust by target system slightly
        tweak = {"generic": 0, "greenhouse": -1, "lever": -1, "workday": -2, "taleo": -2, "icims": -1}.get(target, 0)
        score = max(0, min(100, base + tweak))
        findings.append({"type": "overall", "message": "Overall ATS friendliness score computed from formatting and section heuristics.", "score": score})

    output = {
        "resume_id": resume_id,
        "target_system": target,
        "findings": findings,
        "formatting_issues": formatting_issues if include_fmt else None,
        "section_checks": section_checks if include_sections else None,
        "score": score
    }

    job["prompt_tokens"] = projected_prompt
    job["completion_tokens"] = projected_completion
    job["cost_usd"] = round((projected_total / 1000.0) * 0.01, 6)
    job["output_json"] = output
    job["finished_at"] = now

    if not _set_job_status(job, "succeeded"):
        job["status"] = "failed"
        job["error_code"] = "INVALID_TRANSITION"
        job["error_message"] = "Cannot finish job from current status"
    _save("processing_jobs.json", jobs)

    _record_request("ok", workspace_id, job_id=job_id)
    return {"job": job, "results": output}

def update_parsed_resume(workspace_id, resume_id, parsed_schema_version, parsed_resume_json, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x): return x if isinstance(x, list) else []

    def _log(status, error_code=None, workspace_id_used=None, job_id=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "rmz_req_" + uuid.uuid4().hex.upper()[:19],
            "timestamp": now,
            "endpoint": "update_parsed_resume",
            "workspace_id": workspace_id_used,
            "job_id": job_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    def _month_key(dt): return dt.strftime("%Y-%m")

    def _job_month(job):
        ts = job.get("created_at") or job.get("timestamp") or job.get("started_at") or job.get("updated_at")
        if not isinstance(ts, str) or not ts:
            return _month_key(now_dt)
        try:
            d = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return _month_key(now_dt)
        return d.strftime("%Y-%m")

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:19]

    # ---- validate (relax patterns: tools show 19 but real data includes longer; accept >=18)
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(resume_id, str) or not re.match(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid resume_id.")
    if not isinstance(parsed_schema_version, str) or parsed_schema_version not in ("v1",):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Unsupported parsed_schema_version.")
    if not isinstance(parsed_resume_json, dict):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "parsed_resume_json must be an object.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.")

    # ---- workspace and resume
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Workspace is not active; job creation is not allowed.", workspace_status=ws.get("status"))

    resumes = _ensure_list(_load("resumes.json"))
    resume = next((r for r in resumes if r.get("id") == resume_id), None)
    if not resume or resume.get("workspace_id") != workspace_id:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "Resume not found.")

    # ---- idempotency (job uniqueness constraint)
    jobs = _ensure_list(_load("processing_jobs.json"))
    if idempotency_key is not None and idempotency_key.strip():
        existing = next((j for j in jobs if j.get("workspace_id") == workspace_id and j.get("tool_name") == "update_parsed_resume" and j.get("idempotency_key") == idempotency_key), None)
        if existing:
            _log("ok", None, workspace_id_used=workspace_id, job_id=existing.get("id"))
            return {"job": existing, "resume": resume}

    # ---- quotas for new job
    mk = _month_key(now_dt)
    month_jobs = [j for j in jobs if j.get("workspace_id") == workspace_id and _job_month(j) == mk]
    used_jobs = len(month_jobs)
    used_tokens = 0
    for j in month_jobs:
        pt = j.get("prompt_tokens")
        ct = j.get("completion_tokens")
        if isinstance(pt, int) and pt >= 0: used_tokens += pt
        if isinstance(ct, int) and ct >= 0: used_tokens += ct
    monthly_job_limit = ws.get("monthly_job_limit")
    monthly_token_limit = ws.get("monthly_token_limit")
    if not isinstance(monthly_job_limit, int) or monthly_job_limit < 0: monthly_job_limit = 0
    if not isinstance(monthly_token_limit, int) or monthly_token_limit < 0: monthly_token_limit = 0
    projected_tokens = 400
    if used_jobs + 1 > monthly_job_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Monthly job limit exceeded.", monthly_job_limit=monthly_job_limit, used_jobs=used_jobs)
    if used_tokens + projected_tokens > monthly_token_limit:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Monthly token limit would be exceeded by this request.", monthly_token_limit=monthly_token_limit, used_tokens=used_tokens, projected_tokens=projected_tokens)

    # ---- create processing job (required by business rules)
    job = {
        "id": _gen_id("rmz_job_"),
        "workspace_id": workspace_id,
        "resume_id": resume_id,
        "linkedin_profile_id": None,
        "tool_name": "update_parsed_resume",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {"resume_id": resume_id, "parsed_schema_version": parsed_schema_version},
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": int(projected_tokens * 0.6),
        "completion_tokens": int(projected_tokens * 0.4),
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    # execute
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    resume["parsed_resume_json"] = parsed_resume_json
    resume["parsed_schema_version"] = parsed_schema_version
    if resume.get("status") == "processing":
        resume["status"] = "ready"
    resume["updated_at"] = now
    _save("resumes.json", resumes)

    job["status"] = "succeeded"
    job["finished_at"] = now
    job["updated_at"] = now
    job["output_json"] = {"resume_id": resume_id, "parsed_schema_version": parsed_schema_version}
    _save("processing_jobs.json", jobs)

    _log("ok", None, workspace_id_used=workspace_id, job_id=job.get("id"))
    return {"job": job, "resume": resume}

