    # run
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # apply suggestions: update parsed_resume_json (allowed) and optionally latest_generated_resume_text
    parsed = resume.get("parsed_resume_json")
    if parsed is None or not isinstance(parsed, dict):
        parsed = {"schema_version": "v1"}
    parsed2 = copy.deepcopy(parsed)
    parsed2.setdefault("ats_suggestions_applied", [])
    parsed2["ats_suggestions_applied"].extend(copy.deepcopy(suggestions))
    resume["parsed_resume_json"] = parsed2
    resume["parsed_schema_version"] = "v1"
    resume["updated_at"] = now
    # For this tool, we may write a derived text artifact as a convenience
    resume["latest_generated_resume_text"] = resume.get("latest_generated_resume_text") or "ATS suggestions applied."
