        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x): return x if isinstance(x, list) else []
    def _ensure_dict(x): return x if isinstance(x, dict) else {}

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:19]

    def _log(status, error_code=None, workspace_id_used=None, subscription_id=None, credential_id=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": _new_id("rmz_req_"),
            "timestamp": now,
            "endpoint": "subscribe_to_resource",
            "workspace_id": workspace_id_used,
            "subscription_id": subscription_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    # ---- input validation (schema)
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{19}$", workspace_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "workspace_id must match ^rmz_wsp_[0-9A-Z]{19}$.")
    if not isinstance(resource_type, str) or resource_type not in ("resume", "processing_job", "linkedin_profile"):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "resource_type must be one of: resume, processing_job, linkedin_profile.")
    if not isinstance(resource_id, str) or not resource_id.strip():
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "resource_id must be a non-empty string.")
    if not isinstance(event_types, list) or len(event_types) < 1 or not all(isinstance(x, str) and x.strip() for x in event_types):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "event_types must be a non-empty array of strings.")
    if not isinstance(endpoint_url, str) or not endpoint_url.strip():
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "endpoint_url must be a non-empty string.")
    if not isinstance(secret, str) or not secret.strip():
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "secret must be a non-empty string.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")

    # endpoint_url rule
    try:
        u = urllib.parse.urlparse(endpoint_url)
    except Exception:
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "endpoint_url must be a valid URL.")
    if u.scheme not in ("http", "https") or not u.netloc:
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "endpoint_url must start with http:// or https://.")

    # event types validation (business constraint)
    allowed_events = {
        "resume.updated", "resume.ready", "resume.archived",
        "job.queued", "job.running", "job.succeeded", "job.failed",
        "linkedin.ready", "linkedin.failed",
    }
    bad_events = [e for e in event_types if e not in allowed_events]
    if bad_events:
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err(
            "VALIDATION_ERROR",
            "event_types contains unsupported event type(s).",
            allowed=sorted(allowed_events),
            invalid=bad_events
        )

    # ---- ambient auth: accept if workspace exists and active (suspended/deleted cannot create queued jobs)
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", "UNAUTHORIZED", workspace_id_used=workspace_id)
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # ---- enforce FK integrity for polymorphic resource_id
    resumes = _ensure_list(_load("resumes.json"))
    linkedin = _ensure_list(_load("linkedin_profiles.json"))
    jobs = _ensure_list(_load("processing_jobs.json"))
    target_exists = False
    if resource_type == "resume":
        target_exists = any(isinstance(r, dict) and r.get("id") == resource_id and r.get("workspace_id") == workspace_id for r in resumes)
    elif resource_type == "linkedin_profile":
        target_exists = any(isinstance(p, dict) and p.get("id") == resource_id and p.get("workspace_id") == workspace_id for p in linkedin)
    else:  # processing_job
        target_exists = any(isinstance(j, dict) and j.get("id") == resource_id and j.get("workspace_id") == workspace_id for j in jobs)
    if not target_exists:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id)
        return _err("NOT_FOUND", "resource_id was not found for the given resource_type in this workspace.")

    # ---- quota enforcement (monthly job limit; token limit projection)
    # Every tool execution except list_tools must create a processing_jobs row. This is such a tool.
    # Determine current month window.
    month_start = now_dt.replace(day=1, hour=0, minute=0, second=0)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    ws_jobs = [j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == workspace_id]
    jobs_this_month = 0
    tokens_this_month = 0
    for j in ws_jobs:
        created = _parse_dt(j.get("created_at"))
        if created and created >= month_start:
            jobs_this_month += 1
            pt = j.get("prompt_tokens")
            ct = j.get("completion_tokens")
            if isinstance(pt, int) and pt >= 0:
                tokens_this_month += pt
            if isinstance(ct, int) and ct >= 0:
                tokens_this_month += ct

    mjl = ws.get("monthly_job_limit")
    mtl = ws.get("monthly_token_limit")
    if not isinstance(mjl, int) or mjl < 0:
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Workspace has invalid monthly_job_limit configuration.")
    if not isinstance(mtl, int) or mtl < 0:
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Workspace has invalid monthly_token_limit configuration.")
    if jobs_this_month >= mjl:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Monthly job limit exceeded.", limit=mjl, used=jobs_this_month)

    # projected token usage (this operation is light; still must not exceed cap). Use small conservative estimate.
    projected_tokens = 50
    if tokens_this_month + projected_tokens > mtl:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id)
        return _err("QUOTA_EXCEEDED", "Monthly token limit would be exceeded.", limit=mtl, used=tokens_this_month, projected=projected_tokens)

    # ---- idempotency: tool-level idempotency in processing_jobs (unique(workspace_id, tool_name, idempotency_key))
    tool_name = "subscribe_to_resource"
    if idempotency_key is not None:
        existing_job = next((j for j in ws_jobs if j.get("tool_name") == tool_name and j.get("idempotency_key") == idempotency_key), None)
        if existing_job:
            # If we previously succeeded, return the created/ensured subscription (look up by output_json.subscription_id).
            out = _ensure_dict(existing_job.get("output_json"))
            sub_id = out.get("subscription_id")
            subs = _ensure_list(_load("resource_subscriptions.json"))
            if sub_id and any(isinstance(s, dict) and s.get("id") == sub_id for s in subs):
                _log("ok", None, workspace_id_used=workspace_id, subscription_id=sub_id)
                sub = next(s for s in subs if s.get("id") == sub_id)
                return {"subscription": sub, "job": existing_job}
            # Otherwise, return the existing job state (real systems typically do)
            _log("ok", None, workspace_id_used=workspace_id, subscription_id=None)
            return {"job": existing_job}

    # ---- create processing job (queued -> running -> succeeded/failed)
    job_id = _new_id("rmz_job_")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": resource_id if resource_type == "resume" else None,
        "linkedin_profile_id": resource_id if resource_type == "linkedin_profile" else None,
        "tool_name": tool_name,
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {
            "resource_type": resource_type,
            "resource_id": resource_id,
            "event_types": list(event_types),
            "endpoint_url": endpoint_url
        },
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": projected_tokens,
        "completion_tokens": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    # transition to running
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # ---- upsert subscription: unique(workspace_id, resource_type, resource_id, endpoint_url)
    subs = _ensure_list(_load("resource_subscriptions.json"))
    existing_sub = next(
        (s for s in subs if isinstance(s, dict)
         and s.get("workspace_id") == workspace_id
         and s.get("resource_type") == resource_type
         and s.get("resource_id") == resource_id
         and s.get("endpoint_url") == endpoint_url),
        None
    )

    # If exists and deleted, revive; if exists active/paused, update event_types/secret and ensure active.
    # This aligns with idempotent-ish behaviour in webhook subscription creation.
    if existing_sub:
        # Validate transition if changing status
        cur = existing_sub.get("status")
        if cur not in ("active", "paused", "deleted"):
            job["status"] = "failed"
            job["error_code"] = "VALIDATION_ERROR"
            job["error_message"] = "Existing subscription has invalid status."
            job["finished_at"] = now
            job["updated_at"] = now
            _save("processing_jobs.json", jobs)
            _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id, subscription_id=existing_sub.get("id"))
            return _err("VALIDATION_ERROR", "Existing subscription row is invalid.")

        # allowed transitions for subscriptions
        allowed_transitions = {
            "active": {"paused", "deleted"},
            "paused": {"active", "deleted"},
            "deleted": set()
        }
        target_status = "active"
        if cur != target_status:
            if target_status not in allowed_transitions.get(cur, set()):
                job["status"] = "failed"
                job["error_code"] = "INVALID_TRANSITION"
                job["error_message"] = f"Cannot transition subscription from {cur} to {target_status}."
                job["finished_at"] = now
                job["updated_at"] = now
                _save("processing_jobs.json", jobs)
                _log("error", "INVALID_TRANSITION", workspace_id_used=workspace_id, subscription_id=existing_sub.get("id"))
                return _err("INVALID_TRANSITION", f"Cannot transition subscription from {cur} to {target_status}.")
            existing_sub["status"] = target_status

        existing_sub["event_types"] = list(event_types)
        existing_sub["endpoint_url"] = endpoint_url
        existing_sub["secret"] = secret
        existing_sub["updated_at"] = now
        sub = existing_sub
    else:
        sub = {
            "id": _new_id("rmz_sub_"),
            "workspace_id": workspace_id,
            "status": "active",
            "resource_type": resource_type,
            "resource_id": resource_id,
            "event_types": list(event_types),
            "endpoint_url": endpoint_url,
            "secret": secret,
            "last_notified_at": None,
            "created_at": now,
            "updated_at": now
        }
        subs.append(sub)

    _save("resource_subscriptions.json", subs)

    # finish job succeeded
    job["status"] = "succeeded"
    job["output_json"] = {"subscription_id": sub.get("id")}
    job["finished_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    _log("ok", None, workspace_id_used=workspace_id, subscription_id=sub.get("id"))
    return {"subscription": sub, "job": job}

def unsubscribe_from_resource(workspace_id, subscription_id, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
