        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x): return x if isinstance(x, list) else []
    def _ensure_dict(x): return x if isinstance(x, dict) else {}

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:19]

    def _log(status, error_code=None, workspace_id_used=None, subscription_id_used=None, credential_id=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": _new_id("rmz_req_"),
            "timestamp": now,
            "endpoint": "unsubscribe_from_resource",
            "workspace_id": workspace_id_used,
            "subscription_id": subscription_id_used,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    # ---- validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{19}$", workspace_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("VALIDATION_ERROR", "workspace_id must match ^rmz_wsp_[0-9A-Z]{19}$.")
    if not isinstance(subscription_id, str) or not re.match(r"^rmz_sub_[0-9A-Z]{19}$", subscription_id):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("VALIDATION_ERROR", "subscription_id must match ^rmz_sub_[0-9A-Z]{19}$.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")

    # ---- workspace must exist and be active to create queued job
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", "UNAUTHORIZED", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("UNAUTHORIZED", "Workspace is not active.")

    subs = _ensure_list(_load("resource_subscriptions.json"))
    sub = next((s for s in subs if isinstance(s, dict) and s.get("id") == subscription_id and s.get("workspace_id") == workspace_id), None)
    if not sub:
        _log("error", "NOT_FOUND", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("NOT_FOUND", "Subscription not found.")

    jobs = _ensure_list(_load("processing_jobs.json"))

    # ---- quota enforcement (monthly job limit, token limit projection)
    month_start = now_dt.replace(day=1, hour=0, minute=0, second=0)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    ws_jobs = [j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == workspace_id]
    jobs_this_month = 0
    tokens_this_month = 0
    for j in ws_jobs:
        created = _parse_dt(j.get("created_at"))
        if created and created >= month_start:
            jobs_this_month += 1
            pt = j.get("prompt_tokens")
            ct = j.get("completion_tokens")
            if isinstance(pt, int) and pt >= 0:
                tokens_this_month += pt
            if isinstance(ct, int) and ct >= 0:
                tokens_this_month += ct

    mjl = ws.get("monthly_job_limit")
    mtl = ws.get("monthly_token_limit")
    if not isinstance(mjl, int) or mjl < 0:
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("VALIDATION_ERROR", "Workspace has invalid monthly_job_limit configuration.")
    if not isinstance(mtl, int) or mtl < 0:
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("VALIDATION_ERROR", "Workspace has invalid monthly_token_limit configuration.")
    if jobs_this_month >= mjl:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("QUOTA_EXCEEDED", "Monthly job limit exceeded.", limit=mjl, used=jobs_this_month)

    projected_tokens = 20
    if tokens_this_month + projected_tokens > mtl:
        _log("error", "QUOTA_EXCEEDED", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("QUOTA_EXCEEDED", "Monthly token limit would be exceeded.", limit=mtl, used=tokens_this_month, projected=projected_tokens)

    # ---- idempotency: if a prior unsubscribe job exists for same idempotency_key, return it
    tool_name = "unsubscribe_from_resource"
    if idempotency_key is not None:
        existing_job = next((j for j in ws_jobs if j.get("tool_name") == tool_name and j.get("idempotency_key") == idempotency_key), None)
        if existing_job:
            _log("ok", None, workspace_id_used=workspace_id, subscription_id_used=subscription_id)
            return {"job": existing_job, "subscription": sub}

    # ---- create processing job + transitions
    job_id = _new_id("rmz_job_")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "resume_id": None,
        "linkedin_profile_id": None,
        "tool_name": tool_name,
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {"subscription_id": subscription_id},
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": projected_tokens,
        "completion_tokens": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # ---- transition subscription to deleted (soft delete)
    allowed_transitions = {
        "active": {"paused", "deleted"},
        "paused": {"active", "deleted"},
        "deleted": set()
    }
    cur = sub.get("status")
    if cur not in allowed_transitions:
        job["status"] = "failed"
        job["error_code"] = "VALIDATION_ERROR"
        job["error_message"] = "Subscription has invalid status."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)
        _log("error", "VALIDATION_ERROR", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("VALIDATION_ERROR", "Subscription row is invalid.")
    if cur == "deleted":
        # idempotent: already deleted => succeed with no further change, but job has effect (recorded)
        job["status"] = "succeeded"
        job["output_json"] = {"subscription_id": subscription_id, "already_deleted": True}
        job["finished_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)
        _log("ok", None, workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return {"subscription": sub, "job": job}

    if "deleted" not in allowed_transitions[cur]:
        job["status"] = "failed"
        job["error_code"] = "INVALID_TRANSITION"
        job["error_message"] = f"Cannot transition subscription from {cur} to deleted."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("processing_jobs.json", jobs)
        _log("error", "INVALID_TRANSITION", workspace_id_used=workspace_id, subscription_id_used=subscription_id)
        return _err("INVALID_TRANSITION", f"Cannot transition subscription from {cur} to deleted.")

    sub["status"] = "deleted"
    sub["updated_at"] = now
    _save("resource_subscriptions.json", subs)

    job["status"] = "succeeded"
    job["output_json"] = {"subscription_id": subscription_id, "deleted": True}
    job["finished_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    _log("ok", None, workspace_id_used=workspace_id, subscription_id_used=subscription_id)
    return {"subscription": sub, "job": job}

def list_resource_subscriptions(workspace_id, status=None, resource_type=None, resource_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(x): return x if isinstance(x, list) else []

    def _log(status_code, error_code=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "rmz_req_" + uuid.uuid4().hex.upper()[:19],
            "timestamp": now,
            "endpoint": "list_resource_subscriptions",
            "workspace_id": workspace_id,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split("offset:", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
