def trigger_test_notifications(workspace_id, subscription_id=None, resource_type=None, resource_id=None, event_type=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x): return x if isinstance(x, list) else []

    def _log(status_code, error_code=None, job_id=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "rmz_req_" + uuid.uuid4().hex.upper()[:19],
            "timestamp": now,
            "endpoint": "trigger_test_notifications",
            "workspace_id": workspace_id,
            "job_id": job_id,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    def _month_key(dt): return dt.strftime("%Y-%m")

    def _job_month(job):
        ts = job.get("created_at") or job.get("timestamp") or job.get("started_at") or job.get("updated_at")
        if not isinstance(ts, str) or not ts:
            return _month_key(now_dt)
        try:
            d = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return _month_key(now_dt)
        return d.strftime("%Y-%m")

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:19]

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if subscription_id is not None and (not isinstance(subscription_id, str) or not re.match(r"^rmz_sub_[0-9A-Z]{18,}$", subscription_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid subscription_id.")
    if resource_type is not None and (not isinstance(resource_type, str) or resource_type not in ("resume", "processing_job", "linkedin_profile")):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid resource_type.")
    if resource_id is not None and (not isinstance(resource_id, str) or not resource_id.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "resource_id must be a non-empty string.")
    if not isinstance(event_type, str) or not event_type.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "event_type is required.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.")

    # mutually exclusive filters: if subscription_id provided, ignore resource_type/resource_id but reject if they are also provided (vendor behavior)
    if subscription_id is not None and (resource_type is not None or resource_id is not None):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subscription_id is mutually exclusive with resource_type/resource_id filters.")

    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Workspace is not active; job creation is not allowed.", workspace_status=ws.get("status"))

    jobs = _ensure_list(_load("processing_jobs.json"))
    if idempotency_key is not None and idempotency_key.strip():
        existing = next((j for j in jobs if j.get("workspace_id") == workspace_id and j.get("tool_name") == "trigger_test_notifications" and j.get("idempotency_key") == idempotency_key), None)
        if existing:
            _log("ok", None, job_id=existing.get("id"))
            return {"job": existing}

    # quotas
    mk = _month_key(now_dt)
    month_jobs = [j for j in jobs if j.get("workspace_id") == workspace_id and _job_month(j) == mk]
    used_jobs = len(month_jobs)
    used_tokens = 0
    for j in month_jobs:
        pt = j.get("prompt_tokens")
        ct = j.get("completion_tokens")
        if isinstance(pt, int) and pt >= 0: used_tokens += pt
        if isinstance(ct, int) and ct >= 0: used_tokens += ct
    monthly_job_limit = ws.get("monthly_job_limit")
    monthly_token_limit = ws.get("monthly_token_limit")
    if not isinstance(monthly_job_limit, int) or monthly_job_limit < 0: monthly_job_limit = 0
    if not isinstance(monthly_token_limit, int) or monthly_token_limit < 0: monthly_token_limit = 0
    projected_tokens = 50
    if used_jobs + 1 > monthly_job_limit:
        _log("error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly job limit exceeded.", monthly_job_limit=monthly_job_limit, used_jobs=used_jobs)
    if used_tokens + projected_tokens > monthly_token_limit:
        _log("error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly token limit would be exceeded by this request.", monthly_token_limit=monthly_token_limit, used_tokens=used_tokens, projected_tokens=projected_tokens)

    subs = _ensure_list(_load("resource_subscriptions.json"))
    # choose targets: only active/paused (not deleted)
    if subscription_id is not None:
        targets = [s for s in subs if s.get("id") == subscription_id and s.get("workspace_id") == workspace_id and s.get("status") in ("active", "paused")]
        if not targets:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Subscription not found.")
    else:
        targets = [s for s in subs if s.get("workspace_id") == workspace_id and s.get("status") in ("active", "paused")]
        if resource_type is not None:
            targets = [s for s in targets if s.get("resource_type") == resource_type]
        if resource_id is not None:
            targets = [s for s in targets if s.get("resource_id") == resource_id]

    # create job
    job = {
        "id": _gen_id("rmz_job_"),
        "workspace_id": workspace_id,
        "resume_id": None,
        "linkedin_profile_id": None,
        "tool_name": "trigger_test_notifications",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input_json": {"event_type": event_type, "subscription_id": subscription_id, "resource_type": resource_type, "resource_id": resource_id},
        "output_json": None,
        "error_code": None,
        "error_message": None,
        "cost_usd": 0.0,
        "prompt_tokens": int(projected_tokens * 0.6),
        "completion_tokens": int(projected_tokens * 0.4),
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("processing_jobs.json", jobs)

    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("processing_jobs.json", jobs)

    # attempt delivery (offline): record as "delivered": True for http(s) endpoints, else failed
    deliveries = []
    for s in targets:
        endpoint = s.get("endpoint_url")
        ok = isinstance(endpoint, str) and (endpoint.startswith("https://") or endpoint.startswith("http://"))
        deliveries.append({
            "subscription_id": s.get("id"),
            "endpoint_url": endpoint,
            "event_type": event_type,
            "delivered": bool(ok),
            "attempted_at": now,
            "status_code": 200 if ok else None,
            "error": None if ok else "INVALID_ENDPOINT_URL"
        })
        if ok:
            s["last_notified_at"] = now
            s["updated_at"] = now

    _save("resource_subscriptions.json", subs)

    job["status"] = "succeeded"
    job["finished_at"] = now
    job["updated_at"] = now
    job["output_json"] = {"event_type": event_type, "deliveries": deliveries, "delivered_count": sum(1 for d in deliveries if d["delivered"])}
    _save("processing_jobs.json", jobs)

    _log("ok", None, job_id=job.get("id"))
    return {"job": job}

def list_workspaces(status=None, plan=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, detail=None):
        try:
            candidates = ["request_logs.json", "requests.json", "audit_logs.json", "usage_events.json", "usage.json"]
            existing = None
            for fn in candidates:
                p = os.path.join(_DB, fn)
                if os.path.exists(p):
                    existing = fn
                    break
            if not existing:
                return
            rows = _load(existing)
            row = {
                "id": f"rmz_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "workspace_id": None,
                "status": status_code,
                "detail": detail,
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            }
            if isinstance(rows, list):
                rows.append(row)
                _save(existing, rows)
        except Exception:
            return

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split("offset:", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        return base64.urlsafe_b64encode(f"offset:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            _log("list_workspaces", "error", detail="invalid status")
            return _err("VALIDATION_ERROR", "status is invalid.", field="status")

    if plan is not None:
        if not isinstance(plan, str) or plan not in ("free", "pro", "team", "enterprise"):
            _log("list_workspaces", "error", detail="invalid plan")
            return _err("VALIDATION_ERROR", "plan is invalid.", field="plan")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("list_workspaces", "error", detail="invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    off = _decode_cursor(cursor)
    if off is None:
        _log("list_workspaces", "error", detail="invalid cursor")
        return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    # Ambient auth: no credential parameter exists; treat caller as authenticated.
    # If there are no workspaces at all, return empty list (do not UNAUTHORIZED).
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    filtered = []
    for w in workspaces:
        if not isinstance(w, dict):
            continue
        if status is not None and w.get("status") != status:
            continue
        if plan is not None and w.get("plan") != plan:
            continue
        filtered.append(w)

    # Stable sort: newest first
    def _key(x):
        ca = x.get("created_at") or ""
        return (ca, x.get("id") or "")
    filtered.sort(key=_key, reverse=True)

    total = len(filtered)
    page = filtered[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log("list_workspaces", "ok", detail={"returned": len(page)})
    return resp

def get_resume(workspace_id, resume_id, include_deleted=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    endpoint = "get_resume"

    # ---- Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(resume_id, str) or not re.match(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
        return _err("VALIDATION_ERROR", "Invalid resume_id.")
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")

    # ---- Ambient auth: choose any ACTIVE workspace matching workspace_id
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        # No workspace to authenticate against => unauthorized for workspace access
        # (Spec mentions UNAUTHORIZED/FORBIDDEN; contract doesn't allow FORBIDDEN, use UNAUTHORIZED.)
        _record = {
            "id": None,
            "workspace_id": workspace_id,
            "tool_name": endpoint,
            "status": "failed",
            "idempotency_key": None,
            "input_json": {"workspace_id": workspace_id, "resume_id": resume_id, "include_deleted": include_deleted},
            "output_json": None,
            "error_code": "NOT_FOUND",
            "error_message": "Workspace not found.",
            "cost_usd": 0.0,
            "prompt_tokens": 0,
            "completion_tokens": 0,
            "started_at": None,
            "finished_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
        }
        jobs = _load("processing_jobs.json")
        jobs.append(_record)
        _save("processing_jobs.json", jobs)
        return _err("UNAUTHORIZED", "Workspace not accessible.")

    if ws.get("status") in ("suspended", "deleted"):
        # Allow reads? Tool description says refuses if you cannot access workspace. Treat suspended/deleted as no access.
        jobs = _load("processing_jobs.json")
        jobs.append({
            "id": None,
            "workspace_id": workspace_id,
            "resume_id": resume_id,
            "linkedin_profile_id": None,
            "tool_name": endpoint,
            "status": "failed",
            "idempotency_key": None,
            "input_json": {"workspace_id": workspace_id, "resume_id": resume_id, "include_deleted": include_deleted},
            "output_json": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Workspace not accessible.",
            "cost_usd": 0.0,
            "prompt_tokens": 0,
            "completion_tokens": 0,
            "started_at": None,
            "finished_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
        })
        _save("processing_jobs.json", jobs)
        return _err("UNAUTHORIZED", "Workspace not accessible.")

    resumes = _load("resumes.json")
    r = next((x for x in resumes if x.get("id") == resume_id), None)

    # record dynamics: log call in processing_jobs (best-effort; schema enum doesn't include get_resume)
    # To respect enum constraints, we do NOT create a processing_jobs row for non-tool reads.
    # (Business rule mandates for tool executions except list_tools; reads are tools but schema disallows tool_name.)
    # We still update workspace updated_at to reflect access? No such rule; avoid mutation.
    # ---- Access checks
    if r is None or r.get("workspace_id") != workspace_id:
        return _err("NOT_FOUND", "Resume not found in workspace.")
    if (not include_deleted) and r.get("status") == "deleted":
        return _err("NOT_FOUND", "Resume not found in workspace.")

    # success
    return {"resume": r}

def list_resumes(workspace_id, status=None, source_type=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # ---- Validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    allowed_status = {"draft", "processing", "ready", "archived", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    allowed_source = {"upload", "paste", "generated", "linkedin"}
    if source_type is not None:
        if not isinstance(source_type, str) or source_type not in allowed_source:
            return _err("VALIDATION_ERROR", "Invalid source_type filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # ---- Auth / access
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Workspace not accessible.")

    resumes = _load("resumes.json")
    rows = [r for r in resumes if r.get("workspace_id") == workspace_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if source_type is not None:
        rows = [r for r in rows if r.get("source_type") == source_type]

    # Default behavior: exclude deleted unless explicitly filtered to deleted
    if status is None:
        rows = [r for r in rows if r.get("status") != "deleted"]

    # Sort newest first by created_at then id
    def _key(r):
        return (r.get("created_at") or "", r.get("id") or "")

    rows.sort(key=_key, reverse=True)

    # Cursor: opaque base64 json {"i": start_index, "v": 1}
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("v") == 1 and isinstance(obj.get("i"), int) and obj["i"] >= 0:
                start = obj["i"]
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[start:start + limit]
    next_i = start + len(page)
    has_more = next_i < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"v": 1, "i": next_i}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {"resumes": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

