    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x): return x if isinstance(x, list) else []
    def _new_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:19]

    def _log(status_code, error_code=None, resume_id_used=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": _new_id("rmz_req_"),
            "timestamp": now,
            "endpoint": "update_resume",
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "resume_id": resume_id_used,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    # ---- validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id if isinstance(resume_id, str) else None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(resume_id, str) or not re.match(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id if isinstance(resume_id, str) else None)
        return _err("VALIDATION_ERROR", "Invalid resume_id.")
    if title is not None and not isinstance(title, str):
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id)
        return _err("VALIDATION_ERROR", "title must be a string when provided.")
    allowed_rstatus = {"draft", "processing", "ready", "archived", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_rstatus):
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id)
        return _err("VALIDATION_ERROR", "status must be one of: draft, processing, ready, archived, deleted.")
    if latest_generated_resume_text is not None and not isinstance(latest_generated_resume_text, str):
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id)
        return _err("VALIDATION_ERROR", "latest_generated_resume_text must be a string when provided.")
    allowed_fmt = {"text", "markdown", "html", "docx", "pdf", "json"}
    if latest_generated_format is not None and (not isinstance(latest_generated_format, str) or latest_generated_format not in allowed_fmt):
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id)
        return _err("VALIDATION_ERROR", "latest_generated_format must be one of: text, markdown, html, docx, pdf, json.")

    # must supply at least one mutation
    if title is None and status is None and latest_generated_resume_text is None and latest_generated_format is None:
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id)
        return _err("VALIDATION_ERROR", "At least one updatable field must be provided.")

    # if providing format, also require text (avoid invalid partial state)
    if latest_generated_format is not None and latest_generated_resume_text is None:
        _log("error", "VALIDATION_ERROR", resume_id_used=resume_id)
        return _err("VALIDATION_ERROR", "latest_generated_format cannot be set without latest_generated_resume_text.")

    # ---- workspace existence
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", "NOT_FOUND", resume_id_used=resume_id)
        return _err("NOT_FOUND", "Workspace not found.")

    # ---- resume existence and ownership
    resumes = _ensure_list(_load("resumes.json"))
    r = next((x for x in resumes if isinstance(x, dict) and x.get("id") == resume_id and x.get("workspace_id") == workspace_id), None)
    if not r:
        _log("error", "NOT_FOUND", resume_id_used=resume_id)
        return _err("NOT_FOUND", "Resume not found.")

    # ---- status transition enforcement
    transitions = {
        "draft": {"processing", "ready", "archived", "deleted"},
        "processing": {"ready", "draft", "archived", "deleted"},
        "ready": {"processing", "archived", "deleted"},
        "archived": {"ready", "deleted"},
        "deleted": set()
    }
    if status is not None:
        cur = r.get("status")
        if cur not in transitions:
            _log("error", "VALIDATION_ERROR", resume_id_used=resume_id)
            return _err("VALIDATION_ERROR", "Resume has invalid current status.")
        if status != cur and status not in transitions[cur]:
            _log("error", "INVALID_TRANSITION", resume_id_used=resume_id)
            return _err("INVALID_TRANSITION", f"Cannot transition resume status from {cur} to {status}.")
        # apply transition (or no-op if same)

    # ---- apply updates
    changed = False
    if title is not None and title != r.get("title"):
        r["title"] = title
        changed = True
    if status is not None and status != r.get("status"):
        r["status"] = status
        changed = True
    if latest_generated_resume_text is not None and latest_generated_resume_text != r.get("latest_generated_resume_text"):
        r["latest_generated_resume_text"] = latest_generated_resume_text
        changed = True
    if latest_generated_format is not None and latest_generated_format != r.get("latest_generated_format"):
        r["latest_generated_format"] = latest_generated_format
        changed = True

    if not changed:
        # no success without effect
        _log("error", "CONFLICT", resume_id_used=resume_id)
        return _err("CONFLICT", "No changes to apply (all provided values match current resume).")

    r["updated_at"] = now
    _save("resumes.json", resumes)

    _log("ok", None, resume_id_used=resume_id)
    return {"resume": r}

def list_processing_jobs(workspace_id, status=None, tool_name=None, resume_id=None, linkedin_profile_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # ---- Validate
    if not isinstance(workspace_id, str) or not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    allowed_tools = {
        "extract_resume", "parse_resume", "generate_resume", "update_resume_for_job", "format_converter",
        "anonymize_resume", "grammar_check", "keyword_optimizer", "ats_friendliness_check", "resume_score",
        "skill_gap_analyzer", "summarize_experience", "import_linkedin", "extract_linkedin_profile",
        "extract_linkedin_profile_api", "apply_ats_suggestions", "trigger_test_notifications"
    }
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in allowed_tools:
            return _err("VALIDATION_ERROR", "Invalid tool_name filter.")
    if resume_id is not None:
        if not isinstance(resume_id, str) or not re.match(r"^rmz_rsm_[0-9A-Z]{18,}$", resume_id):
            return _err("VALIDATION_ERROR", "Invalid resume_id filter.")
    if linkedin_profile_id is not None:
        if not isinstance(linkedin_profile_id, str) or not re.match(r"^rmz_lnk_[0-9A-Z]{18,}$", linkedin_profile_id):
            return _err("VALIDATION_ERROR", "Invalid linkedin_profile_id filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # ---- Auth / access
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Workspace not accessible.")

    jobs = _load("processing_jobs.json")
    rows = [j for j in jobs if j.get("workspace_id") == workspace_id]

    if status is not None:
        rows = [j for j in rows if j.get("status") == status]
    if tool_name is not None:
        rows = [j for j in rows if j.get("tool_name") == tool_name]
    if resume_id is not None:
        rows = [j for j in rows if j.get("resume_id") == resume_id]
    if linkedin_profile_id is not None:
        rows = [j for j in rows if j.get("linkedin_profile_id") == linkedin_profile_id]

    # Sort newest first by created_at then id
    def _key(j):
        return (j.get("created_at") or "", j.get("id") or "")

    rows.sort(key=_key, reverse=True)

    # Cursor: opaque base64 json {"i": start_index, "v": 1}
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("v") == 1 and isinstance(obj.get("i"), int) and obj["i"] >= 0:
                start = obj["i"]
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[start:start + limit]
    next_i = start + len(page)
    has_more = next_i < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"v": 1, "i": next_i}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {"processing_jobs": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def get_me(workspace_id=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0244000" if __import__("os").path.isdir("./environment_mix/0244000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request logging / quotas (no explicit schema provided; best-effort if collection exists) ---
    def _append_request_log(endpoint, status, workspace_id_used=None, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            logs = _load(fname)
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "rmz_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "workspace_id": workspace_id_used,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": now,
            })
            _save(fname, logs)
            break

    # --- validate input ---
    if workspace_id is not None:
        if not isinstance(workspace_id, str):
            _append_request_log("get_me", "error", workspace_id_used=None, credential_id=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must be a string")
        if not re.match(r"^rmz_wsp_[0-9A-Z]{18,}$", workspace_id):
            _append_request_log("get_me", "error", workspace_id_used=None, credential_id=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id does not match required pattern")

    # --- authenticate (ambient; no credential param exists). Refuse only if store cannot yield any active identity. ---
    # Since schema provided contains no identities/keys, we resolve an "authenticated context" by selecting a usable workspace.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    selected_ws = None
    if workspace_id is not None:
        for ws in workspaces:
            if isinstance(ws, dict) and ws.get("id") == workspace_id:
                selected_ws = ws
                break
        if selected_ws is None:
            _append_request_log("get_me", "error", workspace_id_used=workspace_id, credential_id=None, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    else:
        # pick an active workspace if any; otherwise any non-deleted; otherwise unauthorized
        for ws in workspaces:
            if isinstance(ws, dict) and ws.get("status") == "active":
                selected_ws = ws
                break
        if selected_ws is None:
            for ws in workspaces:
                if isinstance(ws, dict) and ws.get("status") in ("active", "suspended"):
                    selected_ws = ws
                    break

    if selected_ws is None:
        _append_request_log("get_me", "error", workspace_id_used=None, credential_id=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated context is available (no workspace found)")

    # --- compute entitlements/consumption (best-effort from existing collections) ---
    entitlement = {
        "plan": selected_ws.get("plan"),
        "status": selected_ws.get("status"),
        "limits": {
            "monthly_job_limit": selected_ws.get("monthly_job_limit"),
            "monthly_token_limit": selected_ws.get("monthly_token_limit"),
            "monthly_storage_mb_limit": selected_ws.get("monthly_storage_mb_limit"),
        }
    }

    # month window (UTC calendar month)
    dt_now = datetime.datetime.utcnow()
    month_start = dt_now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    month_start_iso = month_start.isoformat() + "Z"

    # Jobs usage
    jobs = _load("processing_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    jobs_in_month = 0
    tokens_in_month = 0
    # Count "created" jobs in this month; token usage sums prompt+completion if present
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("workspace_id") != selected_ws.get("id"):
            continue
        created_at = j.get("created_at")
        # ISO string compare is okay for Z-less ISO; normalize conservatively
        if isinstance(created_at, str):
            if created_at >= month_start_iso:
                jobs_in_month += 1
                pt = j.get("prompt_tokens", 0)
                ct = j.get("completion_tokens", 0)
                if isinstance(pt, int) and pt >= 0:
                    tokens_in_month += pt
                if isinstance(ct, int) and ct >= 0:
                    tokens_in_month += ct

    # Storage usage: approximate from resumes raw_text size + latest_generated_resume_text size + cover_letter size.
    resumes = _load("resumes.json")
    if not isinstance(resumes, list):
        resumes = []
    total_bytes = 0
    for r in resumes:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != selected_ws.get("id"):
            continue
        for k in ("raw_text", "latest_generated_resume_text", "latest_cover_letter_text"):
            v = r.get(k)
            if isinstance(v, str):
                total_bytes += len(v.encode("utf-8"))
        # add parsed/anonymized json approx
        for k in ("parsed_resume_json", "anonymized_resume_json"):
            v = r.get(k)
            if v is not None:
                try:
                    total_bytes += len(json.dumps(v, ensure_ascii=False).encode("utf-8"))
                except Exception:
                    # if it can't serialize, ignore its contribution rather than failing
                    pass
    storage_mb = total_bytes / (1024.0 * 1024.0)

    consumption = {
        "month_start": month_start_iso,
        "jobs_used": jobs_in_month,
        "tokens_used": tokens_in_month,
        "storage_mb_used_estimate": storage_mb,
    }

    # Identity/scopes: no identity store provided; represent ambient identity and broad scopes.
    # This matches the tool contract while staying consistent with available schema.
    me = {
        "type": "workspace_context",
        "workspace_id": selected_ws.get("id"),
        "workspace_name": selected_ws.get("name"),
    }
    scopes = ["workspaces:read", "resumes:*", "jobs:*", "subscriptions:*", "linkedin:*"]

    resp = {
        "me": me,
        "scopes": scopes,
    }
    # Include entitlement/consumption only when workspace_id provided (as described); otherwise omit or keep minimal.
    if workspace_id is not None:
        resp["workspace"] = {
            "id": selected_ws.get("id"),
            "name": selected_ws.get("name"),
            "status": selected_ws.get("status"),
            "plan": selected_ws.get("plan"),
            "entitlement": entitlement,
            "consumption": consumption,
        }

    _append_request_log("get_me", "ok", workspace_id_used=selected_ws.get("id"), credential_id=None, error_code=None)
    return resp
